    ('be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, 'Quiz — Trois formes à retenir par verbe', 'Allemand', 'Tle', 'Les verbes faibles et les verbes forts', '4bf75d1b-e042-508b-a513-72c0aff3e267'::uuid),
    ('5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, 'Quiz — Six verbes qui changent le sens de la phrase', 'Allemand', 'Tle', 'Les verbes de modalité', '32f8ca79-c449-5457-a322-205f652f59a5'::uuid),
    ('a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, 'Quiz — Le préverbe part à la fin — sauf quand il ne part pas', 'Allemand', 'Tle', 'Les verbes à préverbe séparable', '87dfc174-4738-51a6-b839-41c689507582'::uuid),
    ('45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, 'Quiz — sich, à l’accusatif ou au datif', 'Allemand', 'Tle', 'Les verbes pronominaux', 'fa074bef-514a-56c2-b703-515acda06bf6'::uuid),
    ('9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Quiz — Un seul présent, et il dit aussi le futur', 'Allemand', 'Tle', 'L’indicatif présent', '5244bd2f-b98f-5044-85ab-ebf09aff3a83'::uuid),
    ('062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Quiz — Le passé de l’écrit et du récit', 'Allemand', 'Tle', 'Le prétérit', 'ef1018db-d0b8-51f8-8b72-2cdeff4f824d'::uuid),
    ('388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, 'Quiz — Le passé qu’on parle', 'Allemand', 'Tle', 'Le parfait', '2998f86e-7699-5a60-86f5-51a3445c88e3'::uuid),
    ('ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, 'Quiz — werden + infinitif, et le présent qui suffit souvent', 'Allemand', 'Tle', 'Le futur', 'd253f4a1-0532-5682-ab96-7e3aab3624df'::uuid),
    ('cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, 'Quiz — Trois personnes, trois formes', 'Allemand', 'Tle', 'L’impératif', '937fe040-5383-5263-b862-075ae3207c9c'::uuid),
    ('59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, 'Quiz — würde, hätte, wäre : l’irréel et la politesse', 'Allemand', 'Tle', 'Le subjonctif II présent', '27e67a52-0873-50ba-8f08-0e7b67e4c941'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('244d6dab-901c-5e04-a106-87d5b8090215'::uuid, '52688cc1-b488-50c9-a5b9-5b0b5f289714'::uuid, 'Devant une subordonnée introduite par « dass », la virgule est…', 'mcq', '["Obligatoire","Facultative","Interdite","Remplacée par un tiret"]'::jsonb, 0, 'La virgule allemande sépare des propositions : *Ich weiß, dass er kommt.*', 1),
    ('a870dff7-57d8-5ad2-8049-767db13b859d'::uuid, '52688cc1-b488-50c9-a5b9-5b0b5f289714'::uuid, 'En allemand, on met une virgule devant « und » dans une énumération.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pas de virgule devant *und* ni *oder* ; mais elle est obligatoire devant *aber*, *sondern* et *denn*.', 2),
    ('ea503960-8a40-5cf4-8265-6749dbded311'::uuid, '52688cc1-b488-50c9-a5b9-5b0b5f289714'::uuid, 'Comment s’écrivent les guillemets allemands ?', 'mcq', '["En bas à l’ouverture, en haut à la fermeture","Avec des chevrons, comme en français","Les deux en haut, comme en anglais","Ils n’existent pas"]'::jsonb, 0, '*Er sagt: „Ich komme.“* — et deux-points avant le discours direct.', 3),
    ('fbe140a2-ec68-58f1-8698-d6a3db580595'::uuid, '52688cc1-b488-50c9-a5b9-5b0b5f289714'::uuid, 'Quel groupe infinitif exige une virgule ?', 'mcq', '["Celui introduit par um… zu","Tout groupe contenant zu","Aucun groupe infinitif","Seulement celui introduit par dass"]'::jsonb, 0, '*Ich lerne, um zu bestehen.* Idem pour *ohne… zu* et *statt… zu*.', 4),
    ('ddb702db-9b04-5974-abe8-c6184cee1389'::uuid, '52688cc1-b488-50c9-a5b9-5b0b5f289714'::uuid, 'Un adjectif substantivé prend la majuscule.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*das Wichtigste*, *das Neue* : dès qu’un mot devient nom, il prend la majuscule.', 5),
    ('a46b6b37-e0b2-5d29-b01b-5f87dd4c1aba'::uuid, '52688cc1-b488-50c9-a5b9-5b0b5f289714'::uuid, 'Qu’est-ce qui distingue « Sie » de « sie » à l’écrit ?', 'mcq', '["La majuscule du vouvoiement","L’accent sur le e","Rien du tout","La place dans la phrase"]'::jsonb, 0, 'Le *Sie* de politesse et ses formes (*Ihnen*, *Ihr*) gardent la majuscule.', 6),
    ('304c2361-3802-5f39-8c0b-1af1beceece0'::uuid, '52688cc1-b488-50c9-a5b9-5b0b5f289714'::uuid, 'Après une voyelle brève, on écrit…', 'mcq', '["ss, comme dans Fluss et dass","ß, comme dans Fluß et daß","un s simple","sz"]'::jsonb, 0, '*ß* est réservé aux voyelles longues et aux diphtongues : *Straße*, *heißen*.', 7),
    ('ea18d99f-de6f-5f49-98b9-837a913eb653'::uuid, '52688cc1-b488-50c9-a5b9-5b0b5f289714'::uuid, 'Une subordonnée enchâssée dans la principale est encadrée de deux virgules.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das Buch, das ich lese, ist spannend.*', 8),
    ('80cf9be7-cb03-53f3-90d5-df363d7eb494'::uuid, '99f1dec8-41e0-500e-a25d-9f5f151c7feb'::uuid, 'Dans une déclarative allemande, le verbe conjugué occupe…', 'mcq', '["La deuxième place","La première place","La dernière place","N’importe quelle place"]'::jsonb, 0, 'La deuxième POSITION, c’est-à-dire le deuxième groupe, pas le deuxième mot.', 1),
    ('c6f86747-2223-5e1d-90a8-8ed4686c1285'::uuid, '99f1dec8-41e0-500e-a25d-9f5f151c7feb'::uuid, '« Heute er geht ins Kino » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand un autre élément ouvre la phrase, le sujet passe après le verbe : *Heute geht er…*', 2),
    ('2a25d507-461f-5946-a508-f5fb05e57556'::uuid, '99f1dec8-41e0-500e-a25d-9f5f151c7feb'::uuid, 'Où se place l’infinitif dépendant d’un verbe de modalité ?', 'mcq', '["À la fin de la phrase","Juste après le modal","En première position","Avant le sujet"]'::jsonb, 0, 'C’est la parenthèse verbale : *Ich muss heute Abend arbeiten.*', 3),
    ('3fb63f10-1dc0-50a6-9895-800658028626'::uuid, '99f1dec8-41e0-500e-a25d-9f5f151c7feb'::uuid, 'Que signifie l’ordre TeKaMoLo ?', 'mcq', '["Temps, cause, manière, lieu","Temps, lieu, cause, manière","Lieu, temps, cause, manière","Cause, lieu, temps, manière"]'::jsonb, 0, '*Ich fahre morgen wegen der Arbeit mit dem Zug nach München.*', 4),
    ('dcea42b3-1cae-5126-8420-73d94359188e'::uuid, '99f1dec8-41e0-500e-a25d-9f5f151c7feb'::uuid, 'Avec deux groupes nominaux, l’ordre est datif puis accusatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich gebe dem Kind das Buch.* L’ordre s’inverse si l’accusatif est un pronom.', 5),
    ('b849254b-db3a-5c90-a420-7478c2abaa43'::uuid, '99f1dec8-41e0-500e-a25d-9f5f151c7feb'::uuid, 'Comment traduire « Je le donne à l’enfant » ?', 'mcq', '["Ich gebe es dem Kind","Ich gebe dem Kind es","Ich es gebe dem Kind","Ich gebe dem es Kind"]'::jsonb, 0, 'Le pronom accusatif remonte devant le groupe au datif.', 6),
    ('4257cbc8-653f-5d61-920d-3daa0a27f135'::uuid, '99f1dec8-41e0-500e-a25d-9f5f151c7feb'::uuid, 'Dans « Ich stehe um sieben Uhr auf », « auf » est…', 'mcq', '["Le préverbe séparable, rejeté en fin de phrase","Une préposition de lieu","Un adverbe de temps","Une faute de frappe"]'::jsonb, 0, '*aufstehen* : le préverbe ferme la parenthèse verbale.', 7),
    ('9b5edce8-e743-5ecc-8136-1442910c00ed'::uuid, '99f1dec8-41e0-500e-a25d-9f5f151c7feb'::uuid, '« Nach Berlin fahre ich morgen » est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'N’importe quel groupe peut occuper la première place, tant que le verbe garde la deuxième.', 8),
    ('511d76df-d9fa-5bf5-be24-303b8348febf'::uuid, '5d55f7ea-14c2-533c-bcbf-f6b20bfe2543'::uuid, 'Dans une question fermée, où se place le verbe conjugué ?', 'mcq', '["En première position","En deuxième position","À la fin de la phrase","Juste après le sujet"]'::jsonb, 0, '*Kommst du morgen?* La réponse attendue est *ja*, *nein* ou *doch*.', 1),
    ('408c323e-33bf-527d-ae95-16629ab5fe8f'::uuid, '5d55f7ea-14c2-533c-bcbf-f6b20bfe2543'::uuid, 'Dans une question ouverte, le verbe reste en deuxième position.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le mot en *w-* occupe la première place : *Wann kommst du?*', 2),
    ('93cbff46-ae07-53bd-9c46-33e66a38b29b'::uuid, '5d55f7ea-14c2-533c-bcbf-f6b20bfe2543'::uuid, 'Quelle est la forme accusative de « wer » ?', 'mcq', '["wen","wem","wessen","was"]'::jsonb, 0, '*Wen siehst du?* — *wem* est le datif, *wessen* le génitif.', 3),
    ('2785063f-dc3d-5cc3-be29-da7909a67dfa'::uuid, '5d55f7ea-14c2-533c-bcbf-f6b20bfe2543'::uuid, 'Comment répondre « si ! » à « Du kommst nicht mit? »', 'mcq', '["Doch!","Ja!","Nein!","So!"]'::jsonb, 0, 'Après une question négative, *ja* est impossible : c’est *doch* qui contredit.', 4),
    ('44cb6791-9a40-5694-bac2-f4506483a9de'::uuid, '5d55f7ea-14c2-533c-bcbf-f6b20bfe2543'::uuid, 'Dans une question indirecte, le verbe conjugué se place…', 'mcq', '["À la fin de la subordonnée","En première position","En deuxième position","Devant le sujet"]'::jsonb, 0, '*Ich weiß nicht, wann er kommt.*', 5),
    ('2eaa6ff1-042d-56a2-837e-e687fac6d953'::uuid, '5d55f7ea-14c2-533c-bcbf-f6b20bfe2543'::uuid, 'Le « si » d’une question indirecte se traduit par « wenn ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *ob* : *Ich frage mich, ob er kommt.* *wenn* introduit une condition ou un moment.', 6),
    ('a2cfb921-9232-5e37-9a98-3f05a1f16320'::uuid, '5d55f7ea-14c2-533c-bcbf-f6b20bfe2543'::uuid, 'Que demande « wohin » ?', 'mcq', '["La destination d’un déplacement","Le lieu où l’on se trouve","Le lieu d’où l’on vient","La cause"]'::jsonb, 0, '*wo* = sans mouvement, *wohin* = vers où, *woher* = d’où.', 7),
    ('56f209ae-ea0d-57fe-aba6-59c37187e9b6'::uuid, '5d55f7ea-14c2-533c-bcbf-f6b20bfe2543'::uuid, 'Comment demander « À quoi penses-tu ? »', 'mcq', '["Woran denkst du?","An was denkst du nicht?","Wen denkst du?","Wo denkst du?"]'::jsonb, 0, 'Pour une CHOSE, l’allemand soude *wo(r)-* et la préposition.', 8),
    ('1474e55b-f0b1-5325-a6e5-2aff519cd6aa'::uuid, '9ef8f381-0b89-5507-bbfb-c6e6450fe2dd'::uuid, 'Comment nier « Ich habe ein Auto » ?', 'mcq', '["Ich habe kein Auto","Ich habe nicht ein Auto","Ich habe nicht Auto","Ich habe ein Auto nicht"]'::jsonb, 0, 'Devant un nom avec *ein* ou sans article, c’est *kein*.', 1),
    ('b282c194-768d-5677-a262-a2d0688fe72c'::uuid, '9ef8f381-0b89-5507-bbfb-c6e6450fe2dd'::uuid, 'Comment nier « Ich kenne den Mann » ?', 'mcq', '["Ich kenne den Mann nicht","Ich kenne keinen Mann","Ich kenne den Mann kein","Ich nicht kenne den Mann"]'::jsonb, 0, 'Le nom porte un article défini : la négation est *nicht*, rejetée à droite.', 2),
    ('803deaa3-99e9-51f3-9a7d-3f37b77c98b5'::uuid, '9ef8f381-0b89-5507-bbfb-c6e6450fe2dd'::uuid, '« kein » se décline comme « ein » et possède un pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*keine Freunde*, *keinen Kaffee*, *keinem Kind*.', 3),
    ('39ae4e77-111d-579b-bc64-ed125f1bbf10'::uuid, '9ef8f381-0b89-5507-bbfb-c6e6450fe2dd'::uuid, 'Où se place « nicht » par rapport à un attribut ?', 'mcq', '["Devant l’attribut","Après l’attribut","En fin de phrase","Devant le sujet"]'::jsonb, 0, '*Das Buch ist nicht interessant.*', 4),
    ('16291a6f-0876-5018-9993-ea650bca7b3a'::uuid, '9ef8f381-0b89-5507-bbfb-c6e6450fe2dd'::uuid, 'Dans « Ich habe ihn gestern nicht gesehen », « nicht » se place…', 'mcq', '["Devant le participe passé","Après le participe passé","Juste après l’auxiliaire","En première position"]'::jsonb, 0, '*nicht* va le plus à droite possible, mais reste devant le second morceau du verbe.', 5),
    ('e87f2de6-a41e-5b4f-9937-8946aee0656a'::uuid, '9ef8f381-0b89-5507-bbfb-c6e6450fe2dd'::uuid, 'En allemand, la double négation renforce la négation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une seule négation suffit : *Ich sehe nichts.* C’est l’espagnol qui double.', 6),
    ('20784d45-1778-5fec-a673-c8d3b3254a49'::uuid, '9ef8f381-0b89-5507-bbfb-c6e6450fe2dd'::uuid, 'Que signifie « nicht mehr » ?', 'mcq', '["Ne… plus","Pas encore","Jamais","Nulle part"]'::jsonb, 0, '*noch nicht* signifie « pas encore ».', 7),
    ('170a9a06-5d18-5432-a794-f8a426b45d07'::uuid, '9ef8f381-0b89-5507-bbfb-c6e6450fe2dd'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["sondern","aber","denn","oder"]'::jsonb, 0, '*Er ist nicht Deutscher, sondern Österreicher.* *aber* oppose sans rectifier.', 8),
    ('4405aa53-85e8-5f07-b458-14e5fcc18b03'::uuid, '700e436a-ff06-5750-ad69-2f64746a04d4'::uuid, 'Dans une subordonnée, le verbe conjugué se place…', 'mcq', '["À la fin de la subordonnée","En deuxième position","Juste après la conjonction","En première position"]'::jsonb, 0, '*Ich bleibe zu Hause, weil ich krank bin.*', 1),
    ('d17dc667-ce19-542b-9e68-73a3f3c469d3'::uuid, '700e436a-ff06-5750-ad69-2f64746a04d4'::uuid, 'Dans « …, weil ich gearbeitet habe », quel mot ferme la phrase ?', 'mcq', '["L’auxiliaire conjugué habe","Le participe gearbeitet","Le sujet ich","La conjonction weil"]'::jsonb, 0, 'Le verbe CONJUGUÉ passe après le participe : c’est propre à la subordonnée.', 2),
    ('771859a9-aa19-5bfd-91a5-89ac28c94e54'::uuid, '700e436a-ff06-5750-ad69-2f64746a04d4'::uuid, '« denn » envoie le verbe à la fin, comme « weil ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*denn* est une conjonction de coordination : *Ich bleibe zu Hause, denn ich bin krank.*', 3),
    ('b65d4bec-3455-5d41-82c2-2837fd8d99d1'::uuid, '700e436a-ff06-5750-ad69-2f64746a04d4'::uuid, 'Si la subordonnée ouvre la phrase, que se passe-t-il dans la principale ?', 'mcq', '["Le verbe suit immédiatement la virgule","Le sujet suit immédiatement la virgule","Rien ne change","La principale perd son verbe"]'::jsonb, 0, '*Weil ich krank bin, bleibe ich zu Hause.* La subordonnée occupe la première position.', 4),
    ('be8a754b-e2da-538f-a882-bbccd953a7a1'::uuid, '700e436a-ff06-5750-ad69-2f64746a04d4'::uuid, 'Quelle conjonction traduit « quand » pour un fait unique du passé ?', 'mcq', '["als","wenn","wann","ob"]'::jsonb, 0, '*Als ich zehn Jahre alt war…* — *wenn* vaut pour la répétition ou le présent.', 5),
    ('c84bddab-9e68-5bcf-91a0-cb5f69d2be34'::uuid, '700e436a-ff06-5750-ad69-2f64746a04d4'::uuid, '« wann » peut introduire une subordonnée de temps ordinaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*wann* n’apparaît que dans une question, directe ou indirecte.', 6),
    ('33f3910a-9137-5991-90fb-433c5d257384'::uuid, '700e436a-ff06-5750-ad69-2f64746a04d4'::uuid, 'Que signifie « obwohl » ?', 'mcq', '["Bien que","Parce que","Pour que","Depuis que"]'::jsonb, 0, '*Obwohl es regnet, gehe ich spazieren.*', 7),
    ('fe137314-06fa-5540-b760-08267becbfe5'::uuid, '700e436a-ff06-5750-ad69-2f64746a04d4'::uuid, 'Quelle conjonction exprime le but ?', 'mcq', '["damit","weil","obwohl","nachdem"]'::jsonb, 0, '*Ich lerne, damit ich das Abitur bestehe.*', 8),
    ('33a28384-1d72-5f27-a26b-655945267da3'::uuid, 'c3fa6ce3-7864-5296-85b1-121b0d8d5d33'::uuid, 'Le pronom relatif prend son genre de l’antécédent et son cas…', 'mcq', '["De sa fonction dans la relative","De la fonction de l’antécédent","Du verbe de la principale","Il ne prend jamais de cas"]'::jsonb, 0, 'C’est le raisonnement en deux temps : genre avant, cas après.', 1),
    ('8e6e482d-5232-580d-a200-a583b187bd1c'::uuid, 'c3fa6ce3-7864-5296-85b1-121b0d8d5d33'::uuid, 'Comment traduire « l’homme que je vois » ?', 'mcq', '["Der Mann, den ich sehe","Der Mann, der ich sehe","Der Mann, dem ich sehe","Der Mann, dessen ich sehe"]'::jsonb, 0, 'Masculin + fonction de COD → accusatif *den*.', 2),
    ('113dafbd-7eb5-5be9-9121-81672b599202'::uuid, 'c3fa6ce3-7864-5296-85b1-121b0d8d5d33'::uuid, 'Quelle est la forme du relatif au datif pluriel ?', 'mcq', '["denen","den","deren","die"]'::jsonb, 0, '*Die Freunde, denen ich helfe.* C’est l’une des trois formes qui diffèrent de l’article.', 3),
    ('4f1fe8e9-da5f-5dca-bb98-8bc25267131e'::uuid, 'c3fa6ce3-7864-5296-85b1-121b0d8d5d33'::uuid, 'Dans une relative, le verbe conjugué reste en deuxième position.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La relative est une subordonnée : le verbe conjugué ferme la proposition.', 4),
    ('df2e2481-9063-537f-8daa-9b02c8a4bf0a'::uuid, 'c3fa6ce3-7864-5296-85b1-121b0d8d5d33'::uuid, 'Où se place la préposition dans une relative ?', 'mcq', '["Devant le pronom relatif","À la fin de la relative","Après le verbe","Elle disparaît"]'::jsonb, 0, '*Die Stadt, in der ich wohne.* Et c’est elle qui commande le cas.', 5),
    ('858770af-29dc-58ed-bb99-e9bb557f275e'::uuid, 'c3fa6ce3-7864-5296-85b1-121b0d8d5d33'::uuid, 'Comment traduire « l’homme dont la voiture est en panne » ?', 'mcq', '["Der Mann, dessen Auto kaputt ist","Der Mann, deren Auto kaputt ist","Der Mann, den Auto kaputt ist","Der Mann, wessen Auto kaputt ist"]'::jsonb, 0, 'Génitif masculin *dessen*, et le nom qui suit n’a pas d’article.', 6),
    ('db6c848a-b9a4-570d-8ffd-f839d2a7502e'::uuid, 'c3fa6ce3-7864-5296-85b1-121b0d8d5d33'::uuid, 'Après « alles », « nichts » ou « etwas », le relatif est…', 'mcq', '["was","das","wer","dessen"]'::jsonb, 0, '*Alles, was du sagst, ist richtig.*', 7),
    ('ab9e117f-3e87-54ec-8e10-2112d2aea550'::uuid, 'c3fa6ce3-7864-5296-85b1-121b0d8d5d33'::uuid, '« deren » sert au génitif féminin et au génitif pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Die Frau, deren Sohn…* / *Die Leute, deren Kinder…*', 8),
    ('0e536751-55ec-5fa4-a772-d38844648193'::uuid, 'b641c9e3-d279-5b78-9185-03d1ce15c47f'::uuid, 'Avec quel auxiliaire se construit le passif d’action ?', 'mcq', '["werden","sein","haben","lassen"]'::jsonb, 0, '*Das Haus wird gebaut.* C’est *sein* qui donne le passif d’état.', 1),
    ('b23fde9a-9c0c-595e-b143-23b429989041'::uuid, 'b641c9e3-d279-5b78-9185-03d1ce15c47f'::uuid, 'Comment dit-on « la maison a été construite » ?', 'mcq', '["Das Haus ist gebaut worden","Das Haus ist gebaut geworden","Das Haus hat gebaut worden","Das Haus war gebaut"]'::jsonb, 0, 'Au parfait du passif, le participe de *werden* perd son *ge-* : *worden*.', 2),
    ('a304b128-50a9-5792-94ad-13599728d1d2'::uuid, 'b641c9e3-d279-5b78-9185-03d1ce15c47f'::uuid, '« Das Haus ist gebaut » exprime…', 'mcq', '["Un résultat, un état","Une action en cours","Un futur","Une supposition"]'::jsonb, 0, 'C’est le passif d’état : la photo, pas le film.', 3),
    ('ac9f2b93-8146-55ae-bc5c-caea35f358f3'::uuid, 'b641c9e3-d279-5b78-9185-03d1ce15c47f'::uuid, 'Quel mot introduit l’agent quand c’est une personne ?', 'mcq', '["von + datif","durch + accusatif","mit + datif","für + accusatif"]'::jsonb, 0, '*Das Buch wurde von Goethe geschrieben.* *durch* introduit un moyen.', 4),
    ('5f3cbdf9-1355-56ef-b090-cb698ba1877f'::uuid, 'b641c9e3-d279-5b78-9185-03d1ce15c47f'::uuid, 'L’allemand peut mettre au passif un verbe sans complément d’objet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le passif impersonnel : *Hier wird getanzt.*', 5),
    ('5c145138-cb37-5a7f-9a08-20e7201df28f'::uuid, 'b641c9e3-d279-5b78-9185-03d1ce15c47f'::uuid, 'Comment traduire « le travail doit être fait aujourd’hui » ?', 'mcq', '["Die Arbeit muss heute gemacht werden","Die Arbeit muss heute gemacht worden","Die Arbeit wird heute machen müssen","Die Arbeit ist heute gemacht müssen"]'::jsonb, 0, 'Le modal se conjugue, le passif passe à l’infinitif en fin de phrase.', 6),
    ('37db5dbb-6e1e-5ac8-9edb-b5110bf1d064'::uuid, 'b641c9e3-d279-5b78-9185-03d1ce15c47f'::uuid, '« Er ist Arzt geworden » contient un passif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *werden* employé seul, au sens de « devenir » — d’où *geworden* et non *worden*.', 7),
    ('2748f0bc-4d4f-5f2c-bf9e-9848a16da709'::uuid, 'b641c9e3-d279-5b78-9185-03d1ce15c47f'::uuid, 'Quelle tournure active remplace souvent le passif à l’oral ?', 'mcq', '["man + verbe actif","es gibt","sein + zu","lassen"]'::jsonb, 0, '*Man baut ein Haus* est plus courant que *Ein Haus wird gebaut.*', 8),
    ('ef529f27-6a60-5d42-9b5c-2715859dbe0d'::uuid, '6ccce534-1451-570d-b62e-3526b8c1d0ba'::uuid, 'Où se place « zu » avec un verbe à préverbe séparable ?', 'mcq', '["Entre le préverbe et le radical, en un seul mot","Devant le préverbe","Après l’infinitif","Il disparaît"]'::jsonb, 0, '*einzukaufen*, *aufzustehen*, *anzurufen*.', 1),
    ('45504988-8e16-53dd-aebc-1a7547b324f0'::uuid, '6ccce534-1451-570d-b62e-3526b8c1d0ba'::uuid, 'Après un verbe de modalité, l’infinitif prend « zu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Ich kann schwimmen.* Les modaux, *sehen*, *hören* et *lassen* refusent *zu*.', 2),
    ('322c2044-2e35-50ba-a565-abdb14fecb31'::uuid, '6ccce534-1451-570d-b62e-3526b8c1d0ba'::uuid, 'Comment traduire « J’apprends l’allemand pour étudier à Berlin » ?', 'mcq', '["Ich lerne Deutsch, um in Berlin zu studieren","Ich lerne Deutsch, für in Berlin studieren","Ich lerne Deutsch zu studieren in Berlin","Ich lerne Deutsch, damit in Berlin zu studieren"]'::jsonb, 0, '*um… zu* exprime le but, avec virgule obligatoire.', 3),
    ('12316a5c-056e-5a95-b796-6f436930c3f1'::uuid, '6ccce534-1451-570d-b62e-3526b8c1d0ba'::uuid, 'Quand faut-il employer « damit » plutôt que « um… zu » ?', 'mcq', '["Quand les deux propositions n’ont pas le même sujet","Quand la phrase est négative","Quand le verbe est séparable","Jamais"]'::jsonb, 0, '*Ich erkläre es, damit du es verstehst.*', 4),
    ('14108a78-bbde-52dc-a446-b7bf1d47c228'::uuid, '6ccce534-1451-570d-b62e-3526b8c1d0ba'::uuid, 'Que signifie « ohne etwas zu sagen » ?', 'mcq', '["Sans rien dire","Au lieu de parler","Pour ne rien dire","En disant quelque chose"]'::jsonb, 0, '*statt… zu* signifie « au lieu de ».', 5),
    ('c6754d5b-b408-58b9-ac3e-c1b6a5de75cc'::uuid, '6ccce534-1451-570d-b62e-3526b8c1d0ba'::uuid, '« Ich habe viel zu tun » signifie…', 'mcq', '["J’ai beaucoup à faire","Je dois être fait","Je fais beaucoup","J’aime beaucoup faire"]'::jsonb, 0, '*haben + zu* a une valeur active ; *sein + zu* une valeur passive.', 6),
    ('3b2487e1-9256-5f5c-acac-3127d5e17c4b'::uuid, '6ccce534-1451-570d-b62e-3526b8c1d0ba'::uuid, '« Die Arbeit ist heute zu machen » a une valeur passive.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle équivaut à *Die Arbeit muss heute gemacht werden.*', 7),
    ('a3038f2e-5357-510a-9b65-4259e17f1132'::uuid, '6ccce534-1451-570d-b62e-3526b8c1d0ba'::uuid, 'Après « Ich gehe », le verbe suivant prend « zu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les verbes de mouvement s’en passent : *Ich gehe schwimmen.*', 8),
    ('23000f39-2275-5662-adc4-49ece2d272e5'::uuid, 'd18b9d9f-2c64-5568-b975-bbb719d92e56'::uuid, 'Quel est l’article défini neutre ?', 'mcq', '["das","der","die","den"]'::jsonb, 0, '*das Buch*, *das Haus*, *das Kind*.', 1),
    ('5dae281b-969e-5294-9fbb-a867e9bdd370'::uuid, 'd18b9d9f-2c64-5568-b975-bbb719d92e56'::uuid, 'Au pluriel, l’article défini est « die » pour les trois genres.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*die Männer*, *die Frauen*, *die Kinder*.', 2),
    ('04539ab3-ab23-5b98-a8ec-c782161ea6c0'::uuid, 'd18b9d9f-2c64-5568-b975-bbb719d92e56'::uuid, 'Quel est le genre de « Mädchen » ?', 'mcq', '["Neutre","Féminin","Masculin","Il n’en a pas"]'::jsonb, 0, 'Tous les diminutifs en *-chen* et *-lein* sont neutres, quel que soit le sens.', 3),
    ('e1a38d88-0c3b-5ab6-be58-ce08306d6c0b'::uuid, 'd18b9d9f-2c64-5568-b975-bbb719d92e56'::uuid, 'Les noms en -ung sont généralement…', 'mcq', '["Féminins","Masculins","Neutres","Sans genre"]'::jsonb, 0, '*die Zeitung*, *die Wohnung*, *die Meinung*. Comme les noms en *-heit* et *-keit*.', 4),
    ('67ce5dc3-45dd-5f93-8c36-43a055dc76f9'::uuid, 'd18b9d9f-2c64-5568-b975-bbb719d92e56'::uuid, 'L’article indéfini « ein » possède un pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit simplement *Ich sehe Kinder*. Seule sa négation *kein* a un pluriel.', 5),
    ('fce10edc-d180-501d-9a8c-cd16d98d4c98'::uuid, 'd18b9d9f-2c64-5568-b975-bbb719d92e56'::uuid, 'À quel cas se met le sujet de la phrase ?', 'mcq', '["Au nominatif","À l’accusatif","Au datif","Au génitif"]'::jsonb, 0, 'C’est la forme du dictionnaire : *Der Hund schläft.*', 6),
    ('01a77fb9-f28b-5143-8a29-04fa112ca290'::uuid, 'd18b9d9f-2c64-5568-b975-bbb719d92e56'::uuid, 'Comment traduire « il est professeur » ?', 'mcq', '["Er ist Lehrer","Er ist ein Lehrer","Er ist der Lehrer","Er ist einen Lehrer"]'::jsonb, 0, 'Pas d’article devant un nom de métier après *sein* ou *werden*.', 7),
    ('7f7d328c-18e9-5ab3-b5df-65a9c6b9a22a'::uuid, 'd18b9d9f-2c64-5568-b975-bbb719d92e56'::uuid, 'Dans « Das ist mein Buch », « das » est un article neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un démonstratif invariable qui signifie « ça » : il ne s’accorde à rien.', 8),
    ('fd051c8f-ac87-53f5-8797-a438d6b8191a'::uuid, 'd1f3a71b-ef09-56b3-a646-9218d0cd782d'::uuid, 'À quel cas se met le complément d’objet direct ?', 'mcq', '["À l’accusatif","Au datif","Au nominatif","Au génitif"]'::jsonb, 0, 'Le datif est celui du complément d’objet second.', 1),
    ('95a9cb9d-93d5-5e6f-b0e5-3e0ba4f422dd'::uuid, 'd1f3a71b-ef09-56b3-a646-9218d0cd782d'::uuid, 'Que devient « der » au datif ?', 'mcq', '["dem","den","des","der"]'::jsonb, 0, '*mit dem Mann*. *den* est l’accusatif, *des* le génitif.', 2),
    ('26f85bcc-f5de-55b2-ad22-a40d0e1f0b5b'::uuid, 'd1f3a71b-ef09-56b3-a646-9218d0cd782d'::uuid, 'Que devient « die » (féminin) au datif ?', 'mcq', '["der","dem","den","die"]'::jsonb, 0, 'Piège classique : *der* est à la fois le masculin nominatif et le féminin datif.', 3),
    ('bd661e15-3472-5bff-a32e-7f6f04dfd73b'::uuid, 'd1f3a71b-ef09-56b3-a646-9218d0cd782d'::uuid, 'Au datif pluriel, le nom prend un -n supplémentaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*mit den Kindern*, *aus den Ländern*.', 4),
    ('666c55c6-84c7-5c88-bade-f05b3692b814'::uuid, 'd1f3a71b-ef09-56b3-a646-9218d0cd782d'::uuid, 'Les possessifs se déclinent comme…', 'mcq', '["ein et kein","l’article défini","les adjectifs forts","ils ne se déclinent pas"]'::jsonb, 0, 'D’où leur nom de « déterminants en ein- » : *meinen Bruder*, *meiner Schwester*.', 5),
    ('228e7e9e-7bb2-5b8b-9290-49c20bccfb09'::uuid, 'd1f3a71b-ef09-56b3-a646-9218d0cd782d'::uuid, '« dieser » prend les terminaisons de l’article défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*diesen Mann*, *diesem Kind*, *dieser Frau*. Comme *jeder* et *welcher*.', 6),
    ('3317fea1-f6f9-5cbe-9b31-b7531dfb78af'::uuid, 'd1f3a71b-ef09-56b3-a646-9218d0cd782d'::uuid, 'Au génitif masculin, le nom prend…', 'mcq', '["-(e)s","-n","-er","rien du tout"]'::jsonb, 0, '*das Auto des Vaters*, *das Ende des Jahres*.', 7),
    ('01310d83-0709-5088-a7c9-2ca57e8b81e9'::uuid, 'd1f3a71b-ef09-56b3-a646-9218d0cd782d'::uuid, 'Quel genre change entre le nominatif et l’accusatif ?', 'mcq', '["Le masculin seul","Le féminin seul","Le neutre seul","Les trois genres"]'::jsonb, 0, '*der* → *den*, *ein* → *einen*. Féminin, neutre et pluriel ne bougent pas.', 8),
    ('a18f46aa-6365-5a65-a04d-2f5e2d3995ab'::uuid, 'df28a95d-db7f-580b-a01e-48b0ceb9f3d2'::uuid, 'Quel est le pronom accusatif de « er » ?', 'mcq', '["ihn","ihm","sie","es"]'::jsonb, 0, '*Ich sehe ihn.* *ihm* est le datif.', 1),
    ('2368c9e7-933f-57ec-8add-433a37d0af69'::uuid, 'df28a95d-db7f-580b-a01e-48b0ceb9f3d2'::uuid, 'Comment reprendre « der Tisch » par un pronom ?', 'mcq', '["er","es","sie","ihn"]'::jsonb, 0, 'Le genre GRAMMATICAL commande : un objet masculin se reprend par *er*.', 2),
    ('0888977f-1e42-5bce-9002-a1e663d60b45'::uuid, 'df28a95d-db7f-580b-a01e-48b0ceb9f3d2'::uuid, 'Quel est le pronom datif de « sie » (elle) ?', 'mcq', '["ihr","ihn","ihnen","sie"]'::jsonb, 0, '*Ich helfe ihr.* Ne pas le confondre avec *ihr* = vous (2e personne du pluriel).', 3),
    ('0d1dc9d1-a612-5f83-a32c-f00e1e7fc53e'::uuid, 'df28a95d-db7f-580b-a01e-48b0ceb9f3d2'::uuid, 'Avec deux pronoms compléments, l’ordre est…', 'mcq', '["Accusatif puis datif","Datif puis accusatif","Indifférent","Toujours alphabétique"]'::jsonb, 0, '*Ich gebe es dir* — l’inverse de l’ordre des groupes nominaux.', 4),
    ('bab22369-d96e-55b9-8cd2-95447a997058'::uuid, 'df28a95d-db7f-580b-a01e-48b0ceb9f3d2'::uuid, '« Sie » de politesse se conjugue comme la 3e personne du pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Können Sie mir helfen?* Et il garde toujours sa majuscule.', 5),
    ('aeda941f-a374-56f1-a6d6-49c6299c4e48'::uuid, 'df28a95d-db7f-580b-a01e-48b0ceb9f3d2'::uuid, 'Dans « Es regnet », « es » est…', 'mcq', '["Un sujet apparent","Un COD","Un possessif","Une faute"]'::jsonb, 0, 'Comme dans *Es gibt* : un sujet grammatical vide.', 6),
    ('0b755e53-f5b7-5d8c-b53f-c824e1f1de77'::uuid, 'df28a95d-db7f-580b-a01e-48b0ceb9f3d2'::uuid, '« man » se décline « einen » à l’accusatif et « einem » au datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das macht einen müde.* C’est un pronom indéfini, pas un pronom personnel.', 7),
    ('55529740-769f-5ec0-bcea-9b76a1dbef07'::uuid, 'df28a95d-db7f-580b-a01e-48b0ceb9f3d2'::uuid, 'Où remontent les pronoms compléments dans la phrase ?', 'mcq', '["Juste après le verbe conjugué","À la fin de la phrase","Avant le verbe conjugué","Après le participe passé"]'::jsonb, 0, '*Gestern hat mich mein Vater angerufen* : ils peuvent même précéder le sujet nominal.', 8),
    ('0409789e-fdd4-5e5a-a4b0-fb264f2457e5'::uuid, 'e2928b43-05d1-511c-82f6-3b709bd4689a'::uuid, '« dieser » se décline comme…', 'mcq', '["L’article défini","L’article indéfini","Un adjectif fort","Il ne se décline pas"]'::jsonb, 0, '*diesen Mann*, *diesem Kind*, *dieser Frau*.', 1),
    ('e7a2401f-4c20-51c8-aa8a-5ff1b55bf8b9'::uuid, 'e2928b43-05d1-511c-82f6-3b709bd4689a'::uuid, 'Dans « Den kenne ich gut! », « den » est…', 'mcq', '["Un démonstratif accentué","Un article défini","Un pronom relatif","Une préposition"]'::jsonb, 0, 'C’est la forme démonstrative la plus courante à l’oral.', 2),
    ('6b2859b0-de52-50c0-ace7-d6f293839f8d'::uuid, 'e2928b43-05d1-511c-82f6-3b709bd4689a'::uuid, 'Quelle est la forme du démonstratif au datif pluriel ?', 'mcq', '["denen","den","dessen","deren"]'::jsonb, 0, 'Comme le pronom relatif : *denen* et non *den*.', 3),
    ('d93fa360-b8b9-5382-9b43-7112957046c4'::uuid, 'e2928b43-05d1-511c-82f6-3b709bd4689a'::uuid, '« Ich traf Paul und dessen Bruder » signifie…', 'mcq', '["Le frère de Paul","Mon frère","Le frère de quelqu’un d’autre","Le même frère"]'::jsonb, 0, '*dessen* lève l’ambiguïté que *seinen* laisserait planer.', 4),
    ('31479a6e-48b6-5827-9af7-2c96a1142699'::uuid, 'e2928b43-05d1-511c-82f6-3b709bd4689a'::uuid, '« derselbe » se décline sur ses deux morceaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*in demselben Haus* : *der-* comme l’article, *-selbe* comme un adjectif faible.', 5),
    ('8c7a89f5-5df4-56de-98c9-ef08a2a7a021'::uuid, 'e2928b43-05d1-511c-82f6-3b709bd4689a'::uuid, 'Comment traduire « Ce sont mes parents » ?', 'mcq', '["Das sind meine Eltern","Die sind meine Eltern","Das ist meine Eltern","Diese sind meine Eltern"]'::jsonb, 0, '*das* reste invariable ; le verbe s’accorde avec ce qui suit.', 6),
    ('31eaa4b2-8393-5143-b8df-aa46a56728a0'::uuid, 'e2928b43-05d1-511c-82f6-3b709bd4689a'::uuid, '« dass » et « das » s’emploient indifféremment.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*dass* est la conjonction « que » ; *das* l’article ou le démonstratif. Test : remplacer par *dieses*.', 7),
    ('a4f1cac4-5e95-5baa-a692-8a6479005488'::uuid, 'e2928b43-05d1-511c-82f6-3b709bd4689a'::uuid, '« jener » appartient surtout…', 'mcq', '["À la langue écrite et soutenue","À l’oral familier","Au vocabulaire technique","Au vieil allemand disparu"]'::jsonb, 0, 'À l’oral, on lui préfère *dieser… der da*.', 8),
    ('78961ff9-b4b0-5c27-a036-3f81a8e65e4a'::uuid, 'ef675414-9c2f-57bf-a2f8-3ed60e967425'::uuid, 'Quel est le pluriel de « das Buch » ?', 'mcq', '["die Bücher","die Buche","die Buchs","die Buchen"]'::jsonb, 0, 'Pluriel en *-er* avec inflexion, typique des neutres.', 1),
    ('b28fc506-dacf-5f5e-8cb1-cb4b50637074'::uuid, 'ef675414-9c2f-57bf-a2f8-3ed60e967425'::uuid, 'La quasi-totalité des féminins font leur pluriel en…', 'mcq', '["-(e)n","-e","-er","-s"]'::jsonb, 0, '*die Frauen*, *die Blumen*, *die Zeitungen* — et jamais d’inflexion.', 2),
    ('c9914567-aa34-51d6-ad33-fb28536f7a1c'::uuid, 'ef675414-9c2f-57bf-a2f8-3ed60e967425'::uuid, '« der Lehrer » a le même mot au singulier et au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les masculins en *-er*, *-el*, *-en* ne changent pas : seul l’article le dit.', 3),
    ('fc07f889-cab1-585e-8f42-c6f629c2e7d8'::uuid, 'ef675414-9c2f-57bf-a2f8-3ed60e967425'::uuid, 'Quel est le pluriel de « das Auto » ?', 'mcq', '["die Autos","die Auten","die Autoer","die Aute"]'::jsonb, 0, 'Les emprunts font leur pluriel en *-s*.', 4),
    ('8cd8ce1e-8f94-56f6-a8c3-9f58dba7d92f'::uuid, 'ef675414-9c2f-57bf-a2f8-3ed60e967425'::uuid, 'Au datif pluriel, que prend le nom ?', 'mcq', '["Un -n s’il n’en a pas déjà un","Un -s","Un -er","Rien"]'::jsonb, 0, '*mit den Kindern*, *aus den Städten* — sauf les pluriels en *-s*.', 5),
    ('0fc47694-7d74-5004-b8b2-3d25893749c6'::uuid, 'ef675414-9c2f-57bf-a2f8-3ed60e967425'::uuid, 'Quel est le pluriel de « die Lehrerin » ?', 'mcq', '["die Lehrerinnen","die Lehrerins","die Lehrerine","die Lehrerinen"]'::jsonb, 0, 'Les noms en *-in* doublent le n avant *-en*.', 6),
    ('f7cf69e2-fdc6-542c-affb-3b038807282c'::uuid, 'ef675414-9c2f-57bf-a2f8-3ed60e967425'::uuid, '« die Leute » n’existe qu’au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *die Polizei* ou *die Milch* n’existent qu’au singulier.', 7),
    ('ce6d0520-93cb-5adb-865d-aa635954aaeb'::uuid, 'ef675414-9c2f-57bf-a2f8-3ed60e967425'::uuid, 'Au pluriel, l’article défini dépend du genre du nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *die* pour les trois genres au nominatif et à l’accusatif.', 8),
    ('702ae33e-5df6-510c-8de3-11baf34566b7'::uuid, '7009376e-e262-5a1c-b440-0e7249106e3c'::uuid, 'Après « sein », l’adjectif attribut…', 'mcq', '["Reste invariable","S’accorde en genre","S’accorde en nombre","Prend toujours -e"]'::jsonb, 0, '*Der Mann ist alt*, *die Frau ist alt*, *die Kinder sind alt*.', 1),
    ('761aae6c-b9f6-519f-b62e-a79955258c56'::uuid, '7009376e-e262-5a1c-b440-0e7249106e3c'::uuid, '« Die Frau ist alte » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’attribut ne prend aucune terminaison : *Die Frau ist alt.*', 2),
    ('5513004b-05ae-5a53-a695-1ab1b945997b'::uuid, '7009376e-e262-5a1c-b440-0e7249106e3c'::uuid, 'Quel verbe n’appelle PAS un attribut invariable ?', 'mcq', '["sehen","sein","werden","bleiben"]'::jsonb, 0, '*sein*, *werden* et *bleiben* sont les trois verbes de base de l’attribut.', 3),
    ('e2df3312-1c78-52ec-bf52-479b9889f05f'::uuid, '7009376e-e262-5a1c-b440-0e7249106e3c'::uuid, 'Comment traduire « une vieille femme » ?', 'mcq', '["eine alte Frau","eine alt Frau","ein alte Frau","eine alten Frau"]'::jsonb, 0, 'Devant le nom, l’adjectif est épithète : il se décline.', 4),
    ('a1d19173-fe74-5c69-a222-7a49fc20eaf5'::uuid, '7009376e-e262-5a1c-b440-0e7249106e3c'::uuid, 'En allemand, l’adverbe se forme avec une terminaison spéciale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le même mot sert d’adjectif et d’adverbe : *Er singt schön.*', 5),
    ('b2f2e779-f3d4-5644-b4d6-beda4ff12fb6'::uuid, '7009376e-e262-5a1c-b440-0e7249106e3c'::uuid, 'Dans « Der Zug ist schneller », la terminaison -er marque…', 'mcq', '["Le comparatif","Le masculin","Le pluriel","Le datif"]'::jsonb, 0, 'Ce n’est pas un accord : l’attribut ne s’accorde jamais.', 6),
    ('0d2d5827-c593-5f70-9080-2b1e9a7802bf'::uuid, '7009376e-e262-5a1c-b440-0e7249106e3c'::uuid, 'Comment traduire « je trouve le livre intéressant » ?', 'mcq', '["Ich finde das Buch interessant","Ich finde das Buch interessantes","Ich finde das interessante Buch","Ich finde interessant das Buch"]'::jsonb, 0, '*finden* + COD + attribut invariable.', 7),
    ('88f5d59f-1e95-56b9-bcc4-b12645a96a57'::uuid, '7009376e-e262-5a1c-b440-0e7249106e3c'::uuid, 'La différence entre attribut et épithète tient à la place de l’adjectif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après le verbe : invariable. Devant le nom : décliné.', 8),
    ('7a18de8d-c4f3-5140-94ea-cc12373493fb'::uuid, '216ebc22-e393-542c-954a-2285fa67d094'::uuid, 'Quand l’adjectif prend-il la déclinaison forte ?', 'mcq', '["Quand aucun déterminant ne porte la marque du cas","Après l’article défini","Après ein et kein","Jamais au pluriel"]'::jsonb, 0, '*kalter Kaffee*, *frische Milch* : l’adjectif prend les terminaisons de l’article défini.', 1),
    ('c101dbd7-85ce-5cd4-b0d4-67409167d1a4'::uuid, '216ebc22-e393-542c-954a-2285fa67d094'::uuid, 'Comment traduire « un vieil homme » (nominatif) ?', 'mcq', '["ein alter Mann","ein alt Mann","ein alten Mann","ein alte Mann"]'::jsonb, 0, '*ein* ne marque pas le masculin nominatif : l’adjectif le fait à sa place.', 2),
    ('a487dd2c-f207-52ca-a2fa-1dabd8c79b71'::uuid, '216ebc22-e393-542c-954a-2285fa67d094'::uuid, 'Après « der », l’adjectif prend seulement -e ou -en.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la déclinaison faible : *der alte Mann*, *dem alten Mann*.', 3),
    ('65358361-5dc4-5f0e-bdc0-3578ff50471a'::uuid, '216ebc22-e393-542c-954a-2285fa67d094'::uuid, 'Comment dit-on « une vieille maison » à l’accusatif (das Haus) ?', 'mcq', '["ein altes Haus","ein alten Haus","eine alte Haus","ein alte Haus"]'::jsonb, 0, 'Neutre accusatif : *ein* ne marque rien, l’adjectif prend *-es*.', 4),
    ('76a28fa2-c7bd-53b0-82bd-fccb9f9c0960'::uuid, '216ebc22-e393-542c-954a-2285fa67d094'::uuid, 'Après « meinem », l’adjectif prend…', 'mcq', '["-en","-er","-es","-e"]'::jsonb, 0, 'Le possessif marque déjà le datif : *meinem alten Freund*.', 5),
    ('93d27ce2-e3ef-5404-ba0f-a0c957165797'::uuid, '216ebc22-e393-542c-954a-2285fa67d094'::uuid, '« hoch » garde son c devant une terminaison.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ein hoher Berg*, *das hohe Haus* : le *c* disparaît.', 6),
    ('af8f1355-a0ed-5ec2-8a7e-d05ca61f9b92'::uuid, '216ebc22-e393-542c-954a-2285fa67d094'::uuid, 'Que devient « teuer » dans « ein … Auto » ?', 'mcq', '["teures","teueres","teuers","teuer"]'::jsonb, 0, '*teuer* et *dunkel* perdent leur *e* : *ein teures Auto*, *ein dunkles Zimmer*.', 7),
    ('5b5b47b7-97bb-58cd-85fe-1620b6c74e2b'::uuid, '216ebc22-e393-542c-954a-2285fa67d094'::uuid, '« rosa » et « lila » se déclinent comme les autres adjectifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les adjectifs en *-a* sont invariables : *ein rosa Kleid*.', 8),
    ('7a10e801-5bfb-56dd-8b15-5fd1ee50f938'::uuid, '26a475af-9a11-5a5d-bbab-dc2be6c0be8e'::uuid, 'Comment traduire « Anna et son frère » ?', 'mcq', '["Anna und ihr Bruder","Anna und sein Bruder","Anna und seinen Bruder","Anna und ihre Bruder"]'::jsonb, 0, 'Le radical suit le POSSESSEUR (Anna → *ihr-*), la terminaison l’objet possédé (*Bruder*, masculin).', 1),
    ('ea4b3687-a42d-5156-8d08-5e2b4118305c'::uuid, '26a475af-9a11-5a5d-bbab-dc2be6c0be8e'::uuid, 'Comment traduire « Peter et sa sœur » ?', 'mcq', '["Peter und seine Schwester","Peter und ihre Schwester","Peter und sein Schwester","Peter und ihren Schwester"]'::jsonb, 0, 'Radical *sein-* (Peter), terminaison féminine (*Schwester*).', 2),
    ('6a64897b-7e4b-5fc7-a9f8-2d6abfed49fe'::uuid, '26a475af-9a11-5a5d-bbab-dc2be6c0be8e'::uuid, 'Le possessif se décline comme…', 'mcq', '["ein et kein","l’article défini","un adjectif faible","il ne se décline pas"]'::jsonb, 0, 'Avec en plus un pluriel : *meine Freunde*, *meinen Freunden*.', 3),
    ('2f17fab1-99ea-5966-825f-afadc2468909'::uuid, '26a475af-9a11-5a5d-bbab-dc2be6c0be8e'::uuid, 'Que devient « euer » devant une terminaison ?', 'mcq', '["eur-","euer-","eue-","eur-e-"]'::jsonb, 0, '*eure Mutter*, *euren Vater*. *unser*, lui, garde son *e*.', 4),
    ('b91b7531-6132-5c41-b340-a426b29fa8fa'::uuid, '26a475af-9a11-5a5d-bbab-dc2be6c0be8e'::uuid, '« Ihr » avec majuscule signifie « leur ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec majuscule, c’est le possessif de politesse : « votre ».', 5),
    ('833fb0db-f411-5c62-9cec-dc442b7b7a35'::uuid, '26a475af-9a11-5a5d-bbab-dc2be6c0be8e'::uuid, 'Comment dit-on « je me lave les mains » ?', 'mcq', '["Ich wasche mir die Hände","Ich wasche meine Hände mir","Ich wasche mich die Hände","Ich wasche meinen Händen"]'::jsonb, 0, 'Avec les parties du corps, l’allemand préfère article + datif au possessif.', 6),
    ('282a0ce3-030c-5a83-8fa2-4730d746514c'::uuid, '26a475af-9a11-5a5d-bbab-dc2be6c0be8e'::uuid, 'Employé seul, « mein » prend les terminaisons de l’article défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das ist meins*, *Das ist meiner* : il devient pronom possessif.', 7),
    ('18dc7348-b6cf-5e29-8386-e79726d93ff9'::uuid, '26a475af-9a11-5a5d-bbab-dc2be6c0be8e'::uuid, 'Dans « Das Kind und seine Mutter », pourquoi « seine » ?', 'mcq', '["Parce que « Kind » est neutre, donc radical sein-","Parce que « Mutter » est féminin","Parce que l’enfant est un garçon","Parce que c’est une exception"]'::jsonb, 0, 'Le radical suit le genre GRAMMATICAL du possesseur, pas son sexe.', 8),
    ('8947e95d-5aa8-5a8b-b90f-93f36ea6d2cf'::uuid, '376b8bc6-e549-5295-928f-174263701796'::uuid, 'Comment dit-on « la voiture de Peter » ?', 'mcq', '["Peters Auto","Peter’s Auto","das Auto Peters","der Peter Auto"]'::jsonb, 0, 'Le nom propre passe devant, avec un *-s* sans apostrophe.', 1),
    ('b143a926-7a3c-54d2-80a6-a31121df5eb0'::uuid, '376b8bc6-e549-5295-928f-174263701796'::uuid, 'Comment dit-on « la voiture du père » ?', 'mcq', '["das Auto des Vaters","das Auto der Vater","des Vaters das Auto","das Auto dem Vater"]'::jsonb, 0, 'Génitif masculin : *des* + nom en *-(e)s*, placé derrière.', 2),
    ('851cb105-8a12-5859-9b31-88b493e192b8'::uuid, '376b8bc6-e549-5295-928f-174263701796'::uuid, 'Au génitif féminin, le nom prend un -s.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seuls les masculins et les neutres le prennent : *das Haus der Frau*.', 3),
    ('94ed071d-0a0f-5cd2-a358-3fff8b2d1134'::uuid, '376b8bc6-e549-5295-928f-174263701796'::uuid, 'Quelle question introduit le génitif ?', 'mcq', '["Wessen?","Wem?","Wen?","Wo?"]'::jsonb, 0, '*Wessen Buch ist das?*', 4),
    ('6f5263e8-3089-5bee-a02b-14da27586e9a'::uuid, '376b8bc6-e549-5295-928f-174263701796'::uuid, 'Quelle préposition régit le génitif ?', 'mcq', '["während","mit","für","bei"]'::jsonb, 0, 'Comme *wegen*, *trotz*, *statt*, *innerhalb* : *während des Sommers*.', 5),
    ('8f78fc46-bc42-5a6a-81c3-8dcae9e9b279'::uuid, '376b8bc6-e549-5295-928f-174263701796'::uuid, '« ein Freund von mir » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*von* + datif remplace le génitif, surtout à l’oral.', 6),
    ('163d34d9-d34f-5ace-8960-f29030968896'::uuid, '376b8bc6-e549-5295-928f-174263701796'::uuid, 'Le génitif saxon s’écrit avec une apostrophe, comme en anglais.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Annas Buch*, sans apostrophe — sauf après un son sifflant : *Thomas’ Auto*.', 7),
    ('1126aa3c-8a48-5ef9-a4e6-fa387b1f4637'::uuid, '376b8bc6-e549-5295-928f-174263701796'::uuid, 'Au génitif pluriel, l’article est…', 'mcq', '["der","des","den","die"]'::jsonb, 0, '*die Bücher der Kinder*, sans marque supplémentaire sur le nom.', 8),
    ('68dfe4a4-c935-5bb9-945d-32da462adc2f'::uuid, '6c0dbd25-368f-5910-ae8f-2af40f3f8d67'::uuid, 'Comment forme-t-on le comparatif d’un adjectif long comme « interessant » ?', 'mcq', '["interessanter","mehr interessant","am interessanten","interessant als"]'::jsonb, 0, 'Quelle que soit la longueur du mot, c’est la terminaison *-er*.', 1),
    ('463c3f24-e8e1-5b84-9cd5-9d6c559be35a'::uuid, '6c0dbd25-368f-5910-ae8f-2af40f3f8d67'::uuid, 'Quel mot introduit le second terme d’une comparaison d’inégalité ?', 'mcq', '["als","wie","wenn","denn"]'::jsonb, 0, '*Peter ist größer als Paul.* *wie* sert à l’égalité.', 2),
    ('a717bfc3-0ce3-5681-8d75-a5d3a151e108'::uuid, '6c0dbd25-368f-5910-ae8f-2af40f3f8d67'::uuid, 'Comment dit-on « aussi grand que » ?', 'mcq', '["so groß wie","so groß als","größer wie","als groß wie"]'::jsonb, 0, '*so… wie* pour l’égalité, *…-er als* pour l’inégalité.', 3),
    ('19c04680-5a59-5d36-91a4-5f4aed92307c'::uuid, '6c0dbd25-368f-5910-ae8f-2af40f3f8d67'::uuid, 'Quel est le comparatif de « gut » ?', 'mcq', '["besser","guter","mehr gut","gutter"]'::jsonb, 0, 'Irrégulier, comme *viel → mehr* et *gern → lieber*.', 4),
    ('0b4b5c8a-11f0-5642-8dbc-1054fbe48dcf'::uuid, '6c0dbd25-368f-5910-ae8f-2af40f3f8d67'::uuid, '« Ich trinke lieber Tee » signifie…', 'mcq', '["Je préfère le thé","Je bois beaucoup de thé","Je bois le meilleur thé","J’aimerais du thé"]'::jsonb, 0, '*lieber* est le comparatif de *gern* : c’est ainsi qu’on exprime la préférence.', 5),
    ('e8d663d9-c1ad-560f-b16d-149e6b843075'::uuid, '6c0dbd25-368f-5910-ae8f-2af40f3f8d67'::uuid, 'Devant un nom, le comparatif ne se décline pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ein größeres Haus*, *mein älterer Bruder* : deux terminaisons se suivent.', 6),
    ('082a4148-daaa-55d0-8ca8-4a27e015e53b'::uuid, '6c0dbd25-368f-5910-ae8f-2af40f3f8d67'::uuid, 'Comment dit-on « de plus en plus froid » ?', 'mcq', '["immer kälter","mehr und mehr kalt","so kalt wie","am kältesten"]'::jsonb, 0, '*Es wird immer kälter.* Et *je… desto* pour « plus… plus ».', 7),
    ('f81487e3-2c14-53a6-8ef0-ffcdc4bd0630'::uuid, '6c0dbd25-368f-5910-ae8f-2af40f3f8d67'::uuid, '« mehr groß » est une façon correcte de dire « plus grand ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*mehr* traduit « plus » de quantité ; le comparatif d’un adjectif se fait en *-er*.', 8),
    ('735f08b8-ddc1-5b07-ab70-284c131d609f'::uuid, '5fc85324-3091-549a-9080-704c9d8314df'::uuid, 'Quelle forme du superlatif s’emploie après « sein » ?', 'mcq', '["am + -sten","der + -ste","mehr + adjectif","so + adjectif"]'::jsonb, 0, '*Der Zug ist am schnellsten.* La forme en *der/die/das* est réservée à l’épithète.', 1),
    ('dfb44365-3e4d-5101-aeb4-4cca10824471'::uuid, '5fc85324-3091-549a-9080-704c9d8314df'::uuid, 'Comment dit-on « le train le plus rapide » ?', 'mcq', '["der schnellste Zug","der Zug am schnellsten","am schnellsten Zug","der schneller Zug"]'::jsonb, 0, 'Épithète : article défini + adjectif au superlatif décliné.', 2),
    ('70e2f6e8-a347-590a-8ab5-bd2b50169a72'::uuid, '5fc85324-3091-549a-9080-704c9d8314df'::uuid, 'Pourquoi dit-on « am ältesten » et non « am altsten » ?', 'mcq', '["On intercale un e après d, t, s, ß, z","C’est une exception unique","Le e marque le datif","Pour éviter l’Umlaut"]'::jsonb, 0, 'Un *e* de liaison rend la forme prononçable.', 3),
    ('012912a9-53f7-53dd-907b-48084daa4f42'::uuid, '5fc85324-3091-549a-9080-704c9d8314df'::uuid, 'Quel est le superlatif de « gut » ?', 'mcq', '["am besten","am gutsten","am mehrsten","am guten"]'::jsonb, 0, 'Série irrégulière : *gut → besser → am besten*.', 4),
    ('e379403a-2ed1-58e7-b9e8-53a32de1f915'::uuid, '5fc85324-3091-549a-9080-704c9d8314df'::uuid, '« am liebsten » signifie…', 'mcq', '["Ce que je préfère par-dessus tout","Le plus aimé de tous","Avec amour","Aussi volontiers que"]'::jsonb, 0, '*Am liebsten lese ich Krimis* — une tournure très utile pour donner son avis.', 5),
    ('91e5a185-b685-5aeb-9778-6d9c80006ed5'::uuid, '5fc85324-3091-549a-9080-704c9d8314df'::uuid, 'La forme « am schnellsten » se décline devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est figée ; devant un nom, on passe à *der schnellste*.', 6),
    ('0434ad1d-798c-54e6-8a44-789d8599db2c'::uuid, '5fc85324-3091-549a-9080-704c9d8314df'::uuid, 'Quel est le superlatif de « hoch » ?', 'mcq', '["am höchsten","am hochsten","am höhesten","am hohesten"]'::jsonb, 0, 'Comme *nah → am nächsten* : à apprendre par cœur.', 7),
    ('f8865e76-e50c-5468-9655-3e8950df78dc'::uuid, '5fc85324-3091-549a-9080-704c9d8314df'::uuid, 'Comment introduire le complément d’un superlatif ?', 'mcq', '["von ou unter + datif","als + nominatif","wie + accusatif","für + accusatif"]'::jsonb, 0, '*Er ist der Größte von allen* / *unter seinen Freunden*.', 8),
    ('a69a1ce1-c90d-57e1-b0ba-46c1b39a087b'::uuid, 'bb86c847-698e-5f40-aee6-cc4b498691a9'::uuid, 'Quelles prépositions régissent toujours l’accusatif ?', 'mcq', '["durch, für, gegen, ohne, um","aus, bei, mit, nach, von","an, auf, in, über, unter","wegen, trotz, während"]'::jsonb, 0, 'Une liste à apprendre en bloc : elle ne dépend jamais du sens.', 1),
    ('00dce59e-71a9-5f37-9fd6-4b0bf1e095c1'::uuid, 'bb86c847-698e-5f40-aee6-cc4b498691a9'::uuid, 'Comment traduire « pour mon frère » ?', 'mcq', '["für meinen Bruder","für meinem Bruder","für mein Bruder","für meines Bruders"]'::jsonb, 0, '*für* + accusatif : le masculin devient *meinen*.', 2),
    ('f696eda8-6d32-5132-9dd8-4d0991026e61'::uuid, 'bb86c847-698e-5f40-aee6-cc4b498691a9'::uuid, '« gegen acht Uhr » signifie…', 'mcq', '["Vers huit heures","À huit heures précises","Avant huit heures","Contre huit heures"]'::jsonb, 0, 'Pour l’heure précise, c’est *um acht Uhr*.', 3),
    ('23f58e30-b5e3-5bdd-aa46-f72f57b92864'::uuid, 'bb86c847-698e-5f40-aee6-cc4b498691a9'::uuid, 'Où se place « entlang » ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Devant le verbe"]'::jsonb, 0, '*die Straße entlang* : c’est la seule de la liste à se postposer.', 4),
    ('3ccaf196-e14e-5ce4-96c0-db653c2f9aa3'::uuid, 'bb86c847-698e-5f40-aee6-cc4b498691a9'::uuid, '« für das » se contracte en « fürs ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *durch das → durchs* et *um das → ums*.', 5),
    ('96da7778-80e9-5187-9464-f7264d7485a1'::uuid, 'bb86c847-698e-5f40-aee6-cc4b498691a9'::uuid, 'Comment traduire « sans argent » ?', 'mcq', '["ohne Geld","ohne dem Geld","ohne das Geld haben","ohne Geldes"]'::jsonb, 0, '*ohne* se passe le plus souvent d’article.', 6),
    ('bcd7c19b-5c2b-5ad4-8479-8546446de876'::uuid, 'bb86c847-698e-5f40-aee6-cc4b498691a9'::uuid, 'Comment traduire « pour apprendre » ?', 'mcq', '["um zu lernen","für lernen","für zu lernen","um lernen"]'::jsonb, 0, '*für* introduit un groupe nominal, jamais un verbe : le but se dit *um… zu*.', 7),
    ('346352b1-43e7-5f96-9c0f-0fba84881610'::uuid, 'bb86c847-698e-5f40-aee6-cc4b498691a9'::uuid, '« bis » est souvent suivi d’une seconde préposition.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*bis zum Bahnhof*, *bis zur Brücke* — et c’est alors elle qui commande le cas.', 8),
    ('9b9b997e-f0aa-51a7-b0ee-57ef2c38e4c2'::uuid, '90359f3b-f67f-5ab5-a371-ca0351fd82f7'::uuid, 'Quelle série de prépositions régit le datif ?', 'mcq', '["aus, bei, mit, nach, seit, von, zu","durch, für, gegen, ohne, um","wegen, trotz, während, statt","an, auf, hinter, in, neben"]'::jsonb, 0, 'La formule *aus-bei-mit-nach-seit-von-zu* se retient d’un bloc.', 1),
    ('38fbc782-259d-53b6-9e61-090a55417c96'::uuid, '90359f3b-f67f-5ab5-a371-ca0351fd82f7'::uuid, '« Ich komme aus der Schweiz » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*aus* impose le datif : *die Schweiz* devient *der Schweiz*.', 2),
    ('a131d0ed-e3d1-5146-ac5b-49d6af75efc8'::uuid, '90359f3b-f67f-5ab5-a371-ca0351fd82f7'::uuid, 'En quoi se contracte « zu der » ?', 'mcq', '["zur","zum","zud","zurd"]'::jsonb, 0, '*zur Schule*, *zur Post*. Et *zu dem → zum*.', 3),
    ('948ad581-423e-5904-a4be-c232b22984dc'::uuid, '90359f3b-f67f-5ab5-a371-ca0351fd82f7'::uuid, 'Comment dit-on « je vais chez le médecin » ?', 'mcq', '["Ich gehe zum Arzt","Ich gehe nach dem Arzt","Ich gehe bei dem Arzt","Ich gehe in den Arzt"]'::jsonb, 0, '*zu* + personne vue comme un but ; *bei* dirait où l’on se trouve déjà.', 4),
    ('9515b677-a916-5376-a6ab-782892ddc74a'::uuid, '90359f3b-f67f-5ab5-a371-ca0351fd82f7'::uuid, 'Avec « seit », quel temps emploie-t-on en allemand ?', 'mcq', '["Le présent","Le parfait","Le prétérit","Le futur"]'::jsonb, 0, '*Ich lerne seit drei Jahren Deutsch.*', 5),
    ('69d50168-c4e5-54bb-b2cb-43e955e1f368'::uuid, '90359f3b-f67f-5ab5-a371-ca0351fd82f7'::uuid, 'Comment dit-on « je vais en Suisse » ?', 'mcq', '["Ich fahre in die Schweiz","Ich fahre nach die Schweiz","Ich fahre nach der Schweiz","Ich fahre zu Schweiz"]'::jsonb, 0, 'Les pays qui ont un article prennent *in* + accusatif ; les autres, *nach*.', 6),
    ('9007447d-9e02-5224-8dc2-38d351453a07'::uuid, '90359f3b-f67f-5ab5-a371-ca0351fd82f7'::uuid, '« nach Hause » et « zu Hause » signifient la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*nach Hause* = vers la maison (mouvement), *zu Hause* = à la maison (sans mouvement).', 7),
    ('25e4bad8-0a0d-50af-9748-b0c150707aaf'::uuid, '90359f3b-f67f-5ab5-a371-ca0351fd82f7'::uuid, 'Que signifie « bei » dans « beim Essen » ?', 'mcq', '["Pendant, lors de","Après","Sans","Contre"]'::jsonb, 0, '*bei* couvre aussi le moment d’une action en cours.', 8),
    ('90ecc3a0-3d58-5cb8-81cd-7d371b5245b9'::uuid, '0c1e007f-e03c-52b7-a512-13255cd22234'::uuid, 'Quel cas suit une préposition mixte en cas de déplacement ?', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 0, 'Question *wohin?* → accusatif. Question *wo?* → datif.', 1),
    ('46c3f731-29f9-5b1a-b197-b75208d930ec'::uuid, '0c1e007f-e03c-52b7-a512-13255cd22234'::uuid, '« Ich bin in der Schule » exprime…', 'mcq', '["Une localisation","Un déplacement","Une possession","Une cause"]'::jsonb, 0, 'Question *wo?* → datif.', 2),
    ('fe6066f7-84ec-584c-95f5-9e4f246c18bd'::uuid, '0c1e007f-e03c-52b7-a512-13255cd22234'::uuid, 'Combien y a-t-il de prépositions mixtes ?', 'mcq', '["Neuf","Cinq","Sept","Douze"]'::jsonb, 0, '*an, auf, hinter, in, neben, über, unter, vor, zwischen*.', 3),
    ('ada2726d-b35e-5d9f-8187-474698777dd2'::uuid, '0c1e007f-e03c-52b7-a512-13255cd22234'::uuid, 'Quel verbe demande le datif : « stehen » ou « stellen » ?', 'mcq', '["stehen","stellen","Les deux","Aucun des deux"]'::jsonb, 0, '*stehen* décrit un état (datif) ; *stellen* un déplacement (accusatif).', 4),
    ('20561d43-cf5b-5b3e-8b71-b64d8cfc1927'::uuid, '0c1e007f-e03c-52b7-a512-13255cd22234'::uuid, '« Ich laufe im Park » signifie que je cours à l’intérieur du parc.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*in den Park* dirait que j’y entre. Ce n’est pas le verbe qui décide, mais le changement de lieu.', 5),
    ('dea0b900-a214-5502-98ae-dcd4b5d2ab66'::uuid, '0c1e007f-e03c-52b7-a512-13255cd22234'::uuid, 'En quoi se contracte « in das » ?', 'mcq', '["ins","im","ind","ins dem"]'::jsonb, 0, '*in dem* donne *im* : ne pas les confondre, ils n’ont pas le même cas.', 6),
    ('be4274cc-0d57-5a24-bdcc-ac41d7f9ce68'::uuid, '0c1e007f-e03c-52b7-a512-13255cd22234'::uuid, 'Comment dit-on « en janvier » ?', 'mcq', '["im Januar","in Januar","am Januar","an Januar"]'::jsonb, 0, 'Emploi figé : *im* + mois et saisons, *am* + jours et dates.', 7),
    ('3acd6401-b489-5885-a4e0-b72dbe7c4683'::uuid, '0c1e007f-e03c-52b7-a512-13255cd22234'::uuid, '« sich auf etwas freuen » se construit avec le datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un emploi figé à l’accusatif : *Ich freue mich auf die Ferien.*', 8),
    ('b35e2990-0ca2-5121-af60-f355b1cf4039'::uuid, '9ba10284-a31c-5ba5-a0f4-7407d4faf9d9'::uuid, 'Après « denn », où se place le verbe conjugué ?', 'mcq', '["En deuxième position, comme d’habitude","À la fin de la proposition","En première position","Juste après denn"]'::jsonb, 0, '*denn* est une coordination : il ne compte pas dans l’ordre des mots.', 1),
    ('ef5994fb-c136-5cfb-9290-9e324d25eedb'::uuid, '9ba10284-a31c-5ba5-a0f4-7407d4faf9d9'::uuid, 'Quelle conjonction envoie le verbe à la fin ?', 'mcq', '["weil","denn","aber","und"]'::jsonb, 0, '*weil* subordonne ; *denn* coordonne, pour le même sens.', 2),
    ('195a199d-2631-5e64-a6c6-e965ee6fc768'::uuid, '9ba10284-a31c-5ba5-a0f4-7407d4faf9d9'::uuid, '« sondern » s’emploie…', 'mcq', '["Après une négation, pour rectifier","Après une affirmation","Pour exprimer la cause","Pour exprimer le but"]'::jsonb, 0, '*Das ist nicht mein Buch, sondern deins.*', 3),
    ('8993b22e-f014-52ac-bcbc-1fd61d5e130a'::uuid, '9ba10284-a31c-5ba5-a0f4-7407d4faf9d9'::uuid, 'Que signifie « weder… noch » ?', 'mcq', '["Ni… ni","Ou bien… ou bien","Non seulement… mais aussi","Certes… mais"]'::jsonb, 0, 'La phrase est déjà négative : on n’ajoute pas *nicht*.', 4),
    ('b062e46a-05e6-5537-b062-844c3f279214'::uuid, '9ba10284-a31c-5ba5-a0f4-7407d4faf9d9'::uuid, 'La virgule est obligatoire devant « aber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme devant *sondern* et *denn* ; elle est absente devant *und* et *oder*.', 5),
    ('678568d7-d491-574f-ac67-38c99054a547'::uuid, '9ba10284-a31c-5ba5-a0f4-7407d4faf9d9'::uuid, 'Dans « Es regnet, deshalb bleibe ich zu Hause », pourquoi « bleibe » précède-t-il « ich » ?', 'mcq', '["Parce que deshalb occupe la première position","Parce que c’est une subordonnée","Parce que deshalb est une conjonction","C’est une faute"]'::jsonb, 0, '*deshalb* est un adverbe : il prend la première place et provoque l’inversion.', 6),
    ('46c03f6e-46e1-5e29-864e-0a4fb003d6a1'::uuid, '9ba10284-a31c-5ba5-a0f4-7407d4faf9d9'::uuid, '« entweder… oder » signifie « ou bien… ou bien ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À ne pas confondre avec *sowohl… als auch*, « aussi bien… que ».', 7),
    ('b168d09c-253b-51c5-b019-5b119950983c'::uuid, '9ba10284-a31c-5ba5-a0f4-7407d4faf9d9'::uuid, 'Quelle conjonction s’emploie sans négation devant, pour opposer ?', 'mcq', '["aber","sondern","weder","denn"]'::jsonb, 0, '*Er ist arm, aber glücklich.* *sondern* exige une négation devant lui.', 8),
    ('7b3d87f3-5c07-5c8a-976e-15b86561d9ea'::uuid, '0fdeb96c-5940-5275-962f-9d4c64e4f066'::uuid, 'Quelle question appelle un complément de lieu au datif ?', 'mcq', '["wo?","wohin?","woher?","wann?"]'::jsonb, 0, '*wo?* = localisation → datif. *wohin?* = déplacement → accusatif.', 1),
    ('94574594-243a-5fa3-a41d-ef63089844d9'::uuid, '0fdeb96c-5940-5275-962f-9d4c64e4f066'::uuid, 'Comment dit-on « je vais chez le médecin » ?', 'mcq', '["Ich gehe zum Arzt","Ich gehe beim Arzt","Ich gehe nach dem Arzt","Ich gehe in Arzt"]'::jsonb, 0, '*zu* pour la destination, *bei* pour la localisation : *beim Arzt sein*.', 2),
    ('936e4125-54a3-53cb-91e2-ed3659401dff'::uuid, '0fdeb96c-5940-5275-962f-9d4c64e4f066'::uuid, 'Comment dit-on « je viens de France » ?', 'mcq', '["Ich komme aus Frankreich","Ich komme von Frankreich","Ich komme nach Frankreich","Ich komme in Frankreich"]'::jsonb, 0, '*aus* + pays d’origine ; *von* marque un point de départ ou une personne.', 3),
    ('172e45e7-1cd5-51f8-be1a-14dfba01ec75'::uuid, '0fdeb96c-5940-5275-962f-9d4c64e4f066'::uuid, '« nach » s’emploie devant un pays qui a un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec article, c’est *in* + accusatif : *in die Schweiz*, *in die Türkei*.', 4),
    ('f1158df9-1da3-57ce-80de-8ff9920ddda2'::uuid, '0fdeb96c-5940-5275-962f-9d4c64e4f066'::uuid, 'Que signifie « auf dem Land » ?', 'mcq', '["À la campagne","Sur le pays","Au bord de la mer","À l’étranger"]'::jsonb, 0, 'Et *aufs Land* pour le déplacement : *Wir fahren aufs Land.*', 5),
    ('fceab191-2453-55d6-96b7-88be346adc97'::uuid, '0fdeb96c-5940-5275-962f-9d4c64e4f066'::uuid, 'Que marque la particule « her » ?', 'mcq', '["Le rapprochement vers le locuteur","L’éloignement du locuteur","La répétition","Le passé"]'::jsonb, 0, '*Komm her!* — *hin* marque au contraire l’éloignement.', 6),
    ('7cea9422-c0fb-51cd-98bd-58e51960605b'::uuid, '0fdeb96c-5940-5275-962f-9d4c64e4f066'::uuid, '« Wo gehst du hin? » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La particule de *wohin* peut se détacher et partir en fin de phrase.', 7),
    ('a3113492-4f69-5461-b722-847cc4683299'::uuid, '0fdeb96c-5940-5275-962f-9d4c64e4f066'::uuid, 'Comment dit-on « je rentre à la maison » ?', 'mcq', '["Ich gehe nach Hause","Ich gehe zu Hause","Ich gehe in Hause","Ich gehe im Haus"]'::jsonb, 0, '*nach Hause* pour le mouvement, *zu Hause* pour l’état.', 8),
    ('3f88a3b9-05a9-5d01-a08f-154b10b97417'::uuid, 'ab313f8a-5a94-5275-9eb2-441608abc81c'::uuid, 'Comment dit-on « le lundi » (un lundi précis) ?', 'mcq', '["am Montag","im Montag","um Montag","in Montag"]'::jsonb, 0, '*am* + jours et parties de la journée.', 1),
    ('4cdc2be7-c80c-51f7-9d86-d7ef3dbbb0ef'::uuid, 'ab313f8a-5a94-5275-9eb2-441608abc81c'::uuid, 'Comment dit-on « en été » ?', 'mcq', '["im Sommer","am Sommer","um Sommer","in Sommer"]'::jsonb, 0, '*im* + mois, saisons et années.', 2),
    ('0bd8a42f-9741-5817-adb9-f33551b401e5'::uuid, 'ab313f8a-5a94-5275-9eb2-441608abc81c'::uuid, 'Comment dit-on « à huit heures » ?', 'mcq', '["um acht Uhr","am acht Uhr","im acht Uhr","in acht Uhr"]'::jsonb, 0, '*um* + heure précise.', 3),
    ('f55a5e3b-08e8-5743-a5e7-9c18d034b796'::uuid, 'ab313f8a-5a94-5275-9eb2-441608abc81c'::uuid, '« jeden Tag » est au…', 'mcq', '["Accusatif, sans préposition","Datif, sans préposition","Génitif","Nominatif"]'::jsonb, 0, 'Durées et dates entières se mettent à l’accusatif nu : *letzte Woche*, *den ganzen Tag*.', 4),
    ('4b1e077a-1065-5488-932f-a9688a7ec74f'::uuid, 'ab313f8a-5a94-5275-9eb2-441608abc81c'::uuid, 'Comment dit-on « il y a deux semaines » ?', 'mcq', '["vor zwei Wochen","seit zwei Wochen","in zwei Wochen","ab zwei Wochen"]'::jsonb, 0, '*vor* + datif pour le passé ; *in* + datif pour le futur.', 5),
    ('779da7d4-76c0-5e16-a0a5-cda12d203f2a'::uuid, 'ab313f8a-5a94-5275-9eb2-441608abc81c'::uuid, '« morgens » signifie « demain ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*morgen* = demain, *morgens* = le matin (habituellement).', 6),
    ('1a7f8b5d-33c4-5c48-8377-068f640e1158'::uuid, 'ab313f8a-5a94-5275-9eb2-441608abc81c'::uuid, 'Quelle préposition régit le génitif ?', 'mcq', '["während","seit","ab","bis"]'::jsonb, 0, '*während der Ferien*, *während des Sommers*.', 7),
    ('33ec4d6b-393c-5c7b-a8a8-ec0a5498e6d7'::uuid, 'ab313f8a-5a94-5275-9eb2-441608abc81c'::uuid, 'Où se place le complément de temps parmi les compléments ?', 'mcq', '["En premier","En dernier","Après le lieu","Après la manière"]'::jsonb, 0, 'C’est le *Te* de TeKaMoLo : temps, cause, manière, lieu.', 8),
    ('2748196c-39df-5d34-a38d-985da4dc7f10'::uuid, 'dc2a721c-727c-551c-9785-2a607e7632e9'::uuid, 'Quel auxiliaire s’emploie au parfait avec les verbes de mouvement ?', 'mcq', '["sein","haben","werden","lassen"]'::jsonb, 0, '*Ich bin gefahren*, *ich bin gegangen*.', 1),
    ('48ca668b-724e-5e14-82ea-b765d609d89c'::uuid, 'dc2a721c-727c-551c-9785-2a607e7632e9'::uuid, 'Quel est le prétérit de « haben » à la 1re personne ?', 'mcq', '["ich hatte","ich habte","ich hatt","ich war"]'::jsonb, 0, 'Verbe mixte : radical modifié + terminaison faible.', 2),
    ('12266c12-043d-5793-b723-24161c27c7cf'::uuid, 'dc2a721c-727c-551c-9785-2a607e7632e9'::uuid, '« werden » sert d’auxiliaire au futur ET au passif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich werde kommen* (futur) / *Das Haus wird gebaut* (passif).', 3),
    ('3d430b30-0f41-5184-aa7b-359ad8eb9ef2'::uuid, 'dc2a721c-727c-551c-9785-2a607e7632e9'::uuid, 'Comment se conjugue « sein » à la 2e personne du pluriel ?', 'mcq', '["ihr seid","ihr sind","ihr seit","ihr bist"]'::jsonb, 0, '*seid* avec un d — *seit* avec un t est la préposition « depuis ».', 4),
    ('1b4ee655-778a-516b-be97-a5e1d1a10790'::uuid, 'dc2a721c-727c-551c-9785-2a607e7632e9'::uuid, 'Que signifie « bekommen » ?', 'mcq', '["Recevoir","Devenir","Venir","Convenir"]'::jsonb, 0, 'Faux ami classique : « devenir » se dit *werden*.', 5),
    ('8f8ede39-333d-5bf1-aab9-ca3a0a1b0590'::uuid, 'dc2a721c-727c-551c-9785-2a607e7632e9'::uuid, '« Ich habe das Auto gefahren » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Employé avec un COD, un verbe de mouvement prend *haben*.', 6),
    ('04c612d1-98b7-5f57-b618-9508b267f83e'::uuid, 'dc2a721c-727c-551c-9785-2a607e7632e9'::uuid, 'Quel est le participe passé de « werden » dans un passif ?', 'mcq', '["worden","geworden","gewerdet","werdet"]'::jsonb, 0, '*geworden* est réservé au verbe plein : *Er ist Arzt geworden.*', 7),
    ('65e55ae7-728d-5759-8292-60c4adbddaea'::uuid, 'dc2a721c-727c-551c-9785-2a607e7632e9'::uuid, 'Quel auxiliaire prend « bleiben » au parfait ?', 'mcq', '["sein","haben","werden","les deux au choix"]'::jsonb, 0, '*Ich bin zu Hause geblieben*, comme *sein* et *passieren*.', 8),
    ('cc9a582a-cc66-5ed8-b875-dbb9a6bfeddf'::uuid, 'be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, 'Qu’appelle-t-on les trois temps primitifs d’un verbe ?', 'mcq', '["Infinitif, prétérit, participe II","Présent, futur, passé","Infinitif, présent, parfait","Radical, préverbe, terminaison"]'::jsonb, 0, 'Avec eux, toute la conjugaison se déduit.', 1),
    ('4ca99638-8a22-513c-94e0-d656e27becdb'::uuid, 'be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, 'Quel est le participe passé de « spielen » ?', 'mcq', '["gespielt","gespielen","spielte","gespiel"]'::jsonb, 0, 'Verbe faible : *ge-* + radical + *-t*.', 2),
    ('d2811775-89ae-5c23-ab78-2aed4cd07e88'::uuid, 'be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, 'Un verbe fort change de voyelle au prétérit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’alternance vocalique : *sprechen → sprach*, *fahren → fuhr*.', 3),
    ('87e80019-ae8d-5c8d-877e-8a1be4a6148e'::uuid, 'be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, 'Comment se conjugue « geben » à la 3e personne du singulier ?', 'mcq', '["er gibt","er gebt","er gab","er gibst"]'::jsonb, 0, 'Alternance *e → i* aux 2e et 3e personnes du singulier seulement.', 4),
    ('b2c25e78-9521-5a36-87d6-c2ef8f6be4f0'::uuid, 'be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, 'Comment se conjugue « fahren » à la 2e personne du singulier ?', 'mcq', '["du fährst","du fahrst","du fuhrst","du fährt"]'::jsonb, 0, 'Alternance *a → ä*, qui disparaît au pluriel.', 5),
    ('00e1cfe2-07b6-5001-af69-64290268c3a3'::uuid, 'be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, '« bringen → brachte → gebracht » est un verbe…', 'mcq', '["Mixte","Faible régulier","Fort","Irrégulier isolé"]'::jsonb, 0, 'Radical modifié mais terminaisons faibles, comme *denken* et *wissen*.', 6),
    ('8f5183ef-b714-56ca-813b-2d52b4bf0f5b'::uuid, 'be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, 'Les verbes en -ieren prennent « ge- » au participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*studiert*, *telefoniert*, *fotografiert* : jamais de *ge-*.', 7),
    ('4b65b29e-4395-5d9f-b31c-0ce405986a90'::uuid, 'be8c15a7-8200-592f-b61a-c2319da69fac'::uuid, 'Quel est le prétérit de « schreiben » ?', 'mcq', '["schrieb","schreibte","schrob","geschrieben"]'::jsonb, 0, 'Verbe fort : *schreiben → schrieb → geschrieben*.', 8),
    ('c7e0ea50-14bd-5974-8c3f-e0721a38532c'::uuid, '5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, 'Où se place l’infinitif dépendant d’un modal, dans une principale ?', 'mcq', '["À la fin de la phrase","Juste après le modal","Devant le sujet","En première position"]'::jsonb, 0, '*Ich muss heute Abend arbeiten.*', 1),
    ('883c6c2f-c4d7-501c-8977-244b750ef996'::uuid, '5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, 'Comment se conjugue « können » à la 1re personne du singulier ?', 'mcq', '["ich kann","ich könne","ich kanne","ich könnt"]'::jsonb, 0, 'Les modaux n’ont aucune terminaison aux 1re et 3e personnes du singulier.', 2),
    ('3237ea7e-fb3b-5864-841f-4d8d35bd1a78'::uuid, '5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, '« Ich muss nicht kommen » signifie…', 'mcq', '["Je ne suis pas obligé de venir","Je ne dois pas venir","Je ne peux pas venir","Je ne veux pas venir"]'::jsonb, 0, 'L’interdiction se dit *nicht dürfen* : *Du darfst nicht kommen.*', 3),
    ('9c9b8395-5726-59e3-908c-a866e048235e'::uuid, '5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, 'Quel modal exprime une consigne venue d’autrui ?', 'mcq', '["sollen","wollen","können","mögen"]'::jsonb, 0, '*Ich soll den Arzt fragen* : on m’a dit de le faire.', 4),
    ('58175aa2-21e0-594c-83bb-6d1823484a42'::uuid, '5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, 'Quel est le prétérit de « müssen » ?', 'mcq', '["musste","müsste","mochte","gemusst"]'::jsonb, 0, 'Sans inflexion : *musste*. *müsste* est le subjonctif II.', 5),
    ('27347ee0-2f49-52ec-b453-79acd90ec1a5'::uuid, '5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, 'Au parfait, avec un infinitif dépendant, le modal prend la forme du participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le double infinitif : *Ich habe arbeiten müssen.*', 6),
    ('55347eaa-89b2-5d12-9a4c-4624382c7f10'::uuid, '5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, 'Comment dire poliment « je voudrais un café » ?', 'mcq', '["Ich möchte einen Kaffee","Ich will einen Kaffee","Ich mag einen Kaffee","Ich muss einen Kaffee"]'::jsonb, 0, '*möchte* est le subjonctif II de *mögen* : la forme polie usuelle.', 7),
    ('556a009a-aa24-5aef-884f-9029144732ea'::uuid, '5cd7a2d7-6db5-5032-b83a-633fd09b9a59'::uuid, 'Quel modal exprime l’autorisation ?', 'mcq', '["dürfen","müssen","wollen","sollen"]'::jsonb, 0, '*Darf ich reinkommen?* — *können* dit la capacité.', 8),
    ('ff79e0fb-ec7b-50f3-9aeb-34fb508fedc7'::uuid, 'a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, 'Comment reconnaître un préverbe séparable ?', 'mcq', '["Il porte l’accent du mot","Il commence par be-","Il se termine par -en","Il est toujours plus long"]'::jsonb, 0, '*ÁNrufen* contre *be-SÚCHEN* : le critère s’entend.', 1),
    ('dd94d05e-24d8-5ab0-9a36-cddf77803d4c'::uuid, 'a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, 'Dans une principale, où va le préverbe séparable ?', 'mcq', '["À la fin de la phrase","Devant le verbe","Après le sujet","Il reste soudé"]'::jsonb, 0, '*Ich stehe um sieben Uhr auf.*', 2),
    ('16fa03f6-1bfe-5268-b794-d4ca4963368a'::uuid, 'a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, 'Quel est le participe passé de « aufstehen » ?', 'mcq', '["aufgestanden","geaufstanden","aufstanden","gestandenauf"]'::jsonb, 0, 'Le *ge-* s’intercale entre le préverbe et le radical.', 3),
    ('c6a992bf-ffca-5b11-bc35-9b47669dbde8'::uuid, 'a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, 'Quel est le participe passé de « besuchen » ?', 'mcq', '["besucht","gebesucht","besuchen","gesucht"]'::jsonb, 0, 'Les préverbes inséparables (*be-, ver-, er-, ent-*) interdisent le *ge-*.', 4),
    ('b34c77c8-546f-5c27-bea2-2bde513426ee'::uuid, 'a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, 'Comment écrit-on « einkaufen » avec « zu » ?', 'mcq', '["einzukaufen","zu einkaufen","einkaufen zu","zueinkaufen"]'::jsonb, 0, 'Le *zu* s’intercale, et le tout s’écrit en un seul mot.', 5),
    ('7c658fab-bd75-5fdc-b9f1-39b07978d61e'::uuid, 'a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, 'En subordonnée, le préverbe reste détaché.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le verbe conjugué part à la fin et rejoint son préverbe : *…, weil er aufsteht.*', 6),
    ('8ab5cc2c-8948-52df-b741-f02c8f2e450a'::uuid, 'a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, '« übersetzen » est toujours inséparable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Séparable au sens concret (traverser), inséparable au sens figuré (traduire).', 7),
    ('5ffed887-0803-5f80-9a91-8eee33649496'::uuid, 'a980f86e-e2dc-5c6a-8cc7-bbccd48fdac2'::uuid, 'Que signifie « ankommen » ?', 'mcq', '["Arriver","Venir","Recevoir","Accompagner"]'::jsonb, 0, '*bekommen* = recevoir, *mitkommen* = accompagner : le préverbe fait le sens.', 8),
    ('2ee4422d-29af-59a4-ac40-640bd9587ad2'::uuid, '45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, 'Quelle est la forme du réfléchi à la 3e personne, à l’accusatif comme au datif ?', 'mcq', '["sich","ihn","ihm","es"]'::jsonb, 0, '*sich* couvre les deux cas à la 3e personne, singulier et pluriel.', 1),
    ('914370c9-602d-56f1-aa83-0edc278bbf55'::uuid, '45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, 'Quand emploie-t-on le réfléchi au datif ?', 'mcq', '["Quand la phrase contient déjà un COD","Quand le verbe est fort","Quand la phrase est négative","Quand le sujet est au pluriel"]'::jsonb, 0, '*Ich wasche mir die Hände* : *die Hände* est le COD.', 2),
    ('9e6eab12-1371-57d9-a851-8388c9970f76'::uuid, '45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, 'Comment dit-on « je me lave » (sans complément) ?', 'mcq', '["Ich wasche mich","Ich wasche mir","Ich wasche mich die","Ich wasche sich"]'::jsonb, 0, 'Sans COD, le réfléchi reste à l’accusatif.', 3),
    ('51142bc5-5353-5116-8e5b-ac5a56db59a7'::uuid, '45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, 'Où se place le pronom réfléchi dans une principale ?', 'mcq', '["Juste après le verbe conjugué","À la fin de la phrase","Devant le sujet toujours","Après le participe passé"]'::jsonb, 0, '*Ich freue mich auf die Ferien.*', 4),
    ('d70c9fbd-3e9e-5dd5-9724-74fa8906df0d'::uuid, '45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, '« sich freuen auf » se construit avec…', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 0, 'Comme *sich interessieren für* et *sich erinnern an* : préposition + accusatif.', 5),
    ('ea74ff82-777e-5b0d-a4dc-c9d9c41226b2'::uuid, '45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, '« aufstehen » est un verbe pronominal en allemand.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Se lever » se dit *aufstehen*, sans pronom réfléchi.', 6),
    ('18f81ecf-5f1f-54fc-82cd-c747447e98d5'::uuid, '45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, 'Dans le vouvoiement, « sich » prend une majuscule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Setzen Sie sich bitte!* — seul *Sie* et ses formes possessives la prennent.', 7),
    ('8ac4cc11-321b-5424-bce6-d1d739e8baf6'::uuid, '45c30c44-43a5-5fc7-8f6f-3c991d6d346b'::uuid, 'Comment dit-on « je m’achète un livre » ?', 'mcq', '["Ich kaufe mir ein Buch","Ich kaufe mich ein Buch","Ich kaufe sich ein Buch","Ich kaufe mein Buch"]'::jsonb, 0, 'Il y a un COD (*ein Buch*) : le réfléchi passe au datif.', 8),
    ('a8331dcb-566d-508f-8206-5a04ff57922c'::uuid, '9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Quelle est la terminaison de la 2e personne du singulier ?', 'mcq', '["-st","-t","-e","-en"]'::jsonb, 0, '*du spielst*, *du lernst*, *du wohnst*.', 1),
    ('00c85202-b379-54d8-b833-72789961b4b4'::uuid, '9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Comment se conjugue « arbeiten » à la 3e personne du singulier ?', 'mcq', '["er arbeitet","er arbeitt","er arbeit","er arbeitest"]'::jsonb, 0, 'Radical en *-t* : on intercale un *e* pour pouvoir prononcer.', 2),
    ('9ccc4267-ccfb-5578-88f1-42959d18f3e7'::uuid, '9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Comment se conjugue « heißen » à la 2e personne du singulier ?', 'mcq', '["du heißt","du heißst","du heißest","du heißen"]'::jsonb, 0, 'Après *-s, -ß, -z*, le *-st* perd son *s*.', 3),
    ('1746a3f3-5b2f-5c85-af03-df4f882379a8'::uuid, '9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Le changement de voyelle des verbes forts touche aussi le pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne concerne que les 2e et 3e personnes du singulier : *wir fahren*, pas *wir fähren*.', 4),
    ('5523773d-4f38-53e5-9e59-4f0079ee8a79'::uuid, '9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Comment se conjugue « lesen » à la 3e personne du singulier ?', 'mcq', '["er liest","er lest","er läst","er liesst"]'::jsonb, 0, 'Alternance *e → ie*, et le *-st* fusionne avec le *s* du radical.', 5),
    ('d51e0ffe-92b7-5235-9f91-5d3ee23031de'::uuid, '9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Comment traduire « demain, je vais à Berlin » ?', 'mcq', '["Morgen fahre ich nach Berlin","Morgen ich fahre nach Berlin","Morgen werde ich fahren nach Berlin","Morgen ich werde nach Berlin"]'::jsonb, 0, 'Le présent suffit à dire l’avenir dès qu’un adverbe de temps le précise.', 6),
    ('41f63564-356c-5e82-9c8b-de3d364e4092'::uuid, '9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Avec « seit », l’allemand emploie le parfait.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le présent : *Ich lerne seit drei Jahren Deutsch.*', 7),
    ('5d2c20ea-e47f-5294-baea-718cadbe301d'::uuid, '9cf05752-2888-5e06-9969-fc561dfdaa78'::uuid, 'Comment se conjugue « werden » à la 2e personne du singulier ?', 'mcq', '["du wirst","du werdest","du werdst","du wird"]'::jsonb, 0, '*werde, wirst, wird, werden, werdet, werden*.', 8),
    ('8ae942a0-e2e3-56c8-bc8b-13bf5e400ada'::uuid, '062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Le prétérit est le temps…', 'mcq', '["De l’écrit et du récit","De l’oral courant","Du futur proche","De l’hypothèse"]'::jsonb, 0, 'À l’oral, on raconte au parfait — sauf pour *sein*, *haben* et les modaux.', 1),
    ('691d0d69-c710-509c-96bf-15dea89ac193'::uuid, '062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Quelle est la marque du prétérit des verbes faibles ?', 'mcq', '["-te","-en","-st","Un changement de voyelle"]'::jsonb, 0, '*ich spielte*, *er spielte* : les deux formes sont identiques.', 2),
    ('35a5bed8-b3de-5203-92fb-b77681423e62'::uuid, '062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Quel est le prétérit de « gehen » ?', 'mcq', '["ging","gehte","gang","gegangen"]'::jsonb, 0, 'Verbe fort : *gehen → ging → gegangen*.', 3),
    ('a4339158-ca0a-5ff1-b4c1-27e42d0fb050'::uuid, '062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Aux 1re et 3e personnes, un verbe fort au prétérit ne prend aucune terminaison.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*ich ging*, *er ging* : la forme est nue.', 4),
    ('9d6feebc-9d89-5f7d-9734-b946309f27fb'::uuid, '062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Quel est le prétérit de « wissen » ?', 'mcq', '["wusste","wisste","wieß","gewusst"]'::jsonb, 0, 'Verbe mixte : radical modifié, terminaison faible.', 5),
    ('cc13b33a-e045-5009-8a0b-17a3810f1d52'::uuid, '062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Quels verbes emploie-t-on au prétérit même à l’oral ?', 'mcq', '["sein, haben, werden et les modaux","Tous les verbes forts","Les verbes en -ieren","Aucun"]'::jsonb, 0, '*Ich war müde* est bien plus naturel que *ich bin müde gewesen*.', 6),
    ('e9d0dc11-e503-5fdc-8c96-6ab0d7e0de21'::uuid, '062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Prétérit de haben ou sein + participe II","Présent de werden + infinitif","Prétérit + zu","Parfait + würde"]'::jsonb, 0, '*Ich hatte gegessen*, *er war gegangen* — surtout après *nachdem*.', 7),
    ('b72074a9-9f34-57bf-bb0d-ff287d9cff78'::uuid, '062dbbe9-a42f-59a0-bcee-c534d88dd619'::uuid, 'Quel est le prétérit de « nehmen » ?', 'mcq', '["nahm","nehmte","nimmte","genommen"]'::jsonb, 0, 'Alternance forte : *nehmen → nahm → genommen*.', 8),
    ('e1fae05e-4b16-5a5d-bb48-73466794d054'::uuid, '388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, 'Où se place le participe II dans une principale au parfait ?', 'mcq', '["À la fin de la phrase","Juste après l’auxiliaire","En deuxième position","Devant le sujet"]'::jsonb, 0, 'C’est la parenthèse verbale : l’auxiliaire ouvre, le participe ferme.', 1),
    ('3b7619e0-992a-5569-98ce-0e12073ecdcc'::uuid, '388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, 'Quel est le participe II de « fahren » ?', 'mcq', '["gefahren","gefahrt","fahren","gefuhr"]'::jsonb, 0, 'Verbe fort : *ge-* + radical + *-en*.', 2),
    ('994b58fd-a81d-5f3c-8778-6bd601d67c4b'::uuid, '388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, 'Quel auxiliaire prend « einschlafen » au parfait ?', 'mcq', '["sein","haben","werden","Les deux"]'::jsonb, 0, 'C’est un verbe de changement d’état : *Ich bin eingeschlafen.*', 3),
    ('28987a8a-dfe3-507f-91a7-b69db944467f'::uuid, '388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, 'Quel est le participe II de « telefonieren » ?', 'mcq', '["telefoniert","getelefoniert","telefonierte","getelefonierte"]'::jsonb, 0, 'Les verbes en *-ieren* n’ont jamais de *ge-*.', 4),
    ('87ab4be6-0221-5c88-970b-878dc9c492b4'::uuid, '388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, 'Quel est le participe II de « einkaufen » ?', 'mcq', '["eingekauft","geeinkauft","einkauft","gekaufein"]'::jsonb, 0, 'Préverbe séparable : le *ge-* s’intercale.', 5),
    ('fc056f9d-04d5-5520-a809-27234472f23a'::uuid, '388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, '« Ich habe das Auto gefahren » est une faute.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Employé avec un COD, *fahren* prend *haben*.', 6),
    ('a28bd7a9-9a58-5f58-a9cd-26abd386a11d'::uuid, '388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, 'En subordonnée, où se place l’auxiliaire au parfait ?', 'mcq', '["Après le participe, à la toute fin","En deuxième position","Devant le participe","Il disparaît"]'::jsonb, 0, '*…, weil ich einen Film gesehen habe.*', 7),
    ('77a745cb-f4e5-5c57-b606-a53fc21f1832'::uuid, '388f343c-5e47-5e87-a610-2efe4b7afabe'::uuid, 'Le parfait est le passé de la conversation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le prétérit, lui, est celui du récit écrit.', 8),
    ('a599305e-a25c-59ee-ae92-666ee40efc81'::uuid, 'ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, 'Comment se forme le Futur I ?', 'mcq', '["werden + infinitif","sein + participe II","haben + infinitif","werden + participe II"]'::jsonb, 0, '*Ich werde morgen fahren*, l’infinitif en fin de phrase.', 1),
    ('1154866b-0d6a-5e2d-870c-8cf91f396897'::uuid, 'ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, 'Comment se conjugue « werden » à la 3e personne du singulier ?', 'mcq', '["er wird","er werd","er werdet","er wurde"]'::jsonb, 0, '*ich werde, du wirst, er wird…*', 2),
    ('b5d970ab-81be-53e7-aa7b-f700a39a6d24'::uuid, 'ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, 'Quand le présent suffit-il à exprimer le futur ?', 'mcq', '["Quand un adverbe de temps précise l’avenir","Jamais","Uniquement avec les modaux","Uniquement à l’écrit"]'::jsonb, 0, '*Morgen fahre ich nach Berlin* est la forme la plus courante.', 3),
    ('01619f11-f22b-57a5-8476-57b7b42d4394'::uuid, 'ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, '« Er wird wohl krank sein » signifie…', 'mcq', '["Il doit être malade (supposition)","Il sera malade demain","Il est tombé malade","Il veut être malade"]'::jsonb, 0, 'Le futur exprime aussi une hypothèse sur le présent, souvent avec *wohl*.', 4),
    ('39696b61-efb7-503e-a646-4ce4c45b3cbc'::uuid, 'ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, '« Das Haus wird gebaut » est un futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un passif : *werden* + participe II. Le futur demanderait un infinitif.', 5),
    ('a41c8118-d618-581c-b430-270fde796b01'::uuid, 'ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, 'Que signifie « Er wird Arzt » ?', 'mcq', '["Il devient médecin","Il sera médecin demain","Il est fait médecin","Il doit être médecin"]'::jsonb, 0, '*werden* + nom : c’est le verbe plein « devenir ».', 6),
    ('9ebee048-dbac-531e-a1a0-ceeb1ca0a379'::uuid, 'ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, 'En subordonnée, quel mot ferme une phrase au futur ?', 'mcq', '["werden conjugué","L’infinitif","Le sujet","La conjonction"]'::jsonb, 0, '*…, dass er kommen wird.*', 7),
    ('a8311c1c-4e29-5f68-a2c9-f1b3d243e680'::uuid, 'ad0982bb-b45e-5718-81b8-103e67f073b3'::uuid, 'Le Futur II exprime une action achevée dans l’avenir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Bis morgen werde ich das Buch gelesen haben* — ou une supposition sur le passé.', 8),
    ('d666956a-6d73-5723-865b-80db140ff98e'::uuid, 'cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, 'Quelle est la forme d’impératif de « kommen » pour « du » ?', 'mcq', '["Komm!","Kommst!","Komme du!","Kommen!"]'::jsonb, 0, 'Radical sans terminaison et sans pronom.', 1),
    ('47dffcc9-9e31-57bd-bece-1e5ef9430af5'::uuid, 'cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, 'Comment dit-on « Donne ! » (du) ?', 'mcq', '["Gib!","Geb!","Gebe!","Gibst!"]'::jsonb, 0, 'L’alternance *e → i* se maintient à l’impératif.', 2),
    ('77e0d00d-bdba-5ee7-8645-a57270071fde'::uuid, 'cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, '« Fahre! » garde-t-il l’inflexion de « du fährst » ?', 'mcq', '["Non, on dit Fahr!","Oui, on dit Fähr!","Oui, on dit Fährst!","Les deux sont possibles"]'::jsonb, 0, 'L’alternance *a → ä* disparaît à l’impératif.', 3),
    ('b62e1729-a49d-537a-a082-81c93ac0caf1'::uuid, 'cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, 'À la forme de politesse, le pronom « Sie » se maintient.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Kommen Sie!*, *Setzen Sie sich!* — contrairement aux formes du *du* et du *ihr*.', 4),
    ('8d7bea49-5520-5305-b129-6c3b54f0aa55'::uuid, 'cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, 'Quelle est la forme d’impératif de « sein » pour « ihr » ?', 'mcq', '["Seid ruhig!","Sei ruhig!","Seien ruhig!","Seid Sie ruhig!"]'::jsonb, 0, '*Sei* (du), *Seid* (ihr), *Seien Sie* (politesse).', 5),
    ('52de0299-a10c-5fa6-845a-4630913792f6'::uuid, 'cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, 'À quoi servent « doch » et « mal » dans un impératif ?', 'mcq', '["À adoucir l’ordre","À le renforcer","À le nier","À marquer le passé"]'::jsonb, 0, 'Sans eux, un impératif allemand paraît très sec.', 6),
    ('1f4b6a66-20d2-576a-af6b-9bdf9a86394a'::uuid, 'cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, 'Où part le préverbe séparable à l’impératif ?', 'mcq', '["À la fin de la phrase","Devant le verbe","Il reste soudé","Après le sujet"]'::jsonb, 0, '*Ruf mich an!*, *Steh bitte auf!*', 7),
    ('38254153-3b58-54af-bcf0-358062d4affe'::uuid, 'cba3d521-c5d8-5fc7-a320-a880357a44f6'::uuid, '« Nicht rauchen! » est un impératif conjugué.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un infinitif employé comme consigne, typique des panneaux.', 8),
    ('47e00cc1-83cd-5622-b3da-8e31b3c9b27f'::uuid, '59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, 'Quelle est la construction usuelle du subjonctif II ?', 'mcq', '["würde + infinitif","werden + participe II","hätte + infinitif","sein + zu + infinitif"]'::jsonb, 0, '*Ich würde gern nach Berlin fahren.*', 1),
    ('e50e69f8-06f9-5cee-864a-088d3a192814'::uuid, '59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, 'Quelle est la forme de subjonctif II de « sein » ?', 'mcq', '["wäre","wurde","sei","war"]'::jsonb, 0, 'Formée sur le prétérit *war*, avec inflexion et *-e*.', 2),
    ('7b036269-17cc-5090-99ed-d516695a9cd2'::uuid, '59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, 'Comment traduire « je voudrais un café » ?', 'mcq', '["Ich hätte gern einen Kaffee","Ich habe gern einen Kaffee","Ich würde einen Kaffee","Ich will einen Kaffee"]'::jsonb, 0, '*hätte gern* est la formule de politesse standard.', 3),
    ('6c08a253-8e77-55fd-a4fb-e06eb89ff487'::uuid, '59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, 'Dans « Wenn ich Zeit hätte, würde ich kommen », combien de verbes sont au subjonctif II ?', 'mcq', '["Deux","Un seul","Aucun","Trois"]'::jsonb, 0, 'La subordonnée et la principale le portent toutes les deux.', 4),
    ('569cc111-5975-53fc-bb70-e9174efbccf9'::uuid, '59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, '« Wenn » peut être omis, le verbe prenant alors la première place.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hätte ich Zeit, würde ich kommen.*', 5),
    ('175055a9-a96d-5bbf-bf72-110e19fd234e'::uuid, '59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, 'Quelle est la forme de subjonctif II de « können » ?', 'mcq', '["könnte","konnte","kann","könne"]'::jsonb, 0, '*Könnten Sie mir helfen?* — sans inflexion, c’est le prétérit *konnte*.', 6),
    ('82743f7d-bf08-5c48-b079-1bfd8dd535c3'::uuid, '59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, 'Après « als ob », quel mode emploie-t-on ?', 'mcq', '["Le subjonctif II","L’indicatif présent","L’impératif","Le futur"]'::jsonb, 0, '*Er tut so, als ob er alles wüsste.*', 7),
    ('66d48d04-59bc-5af6-a580-3e24341f4828'::uuid, '59956da0-6937-54bc-8e83-b2c389a30da3'::uuid, '« Du solltest mehr schlafen » exprime…', 'mcq', '["Un conseil","Une obligation stricte","une interdiction","Un fait passé"]'::jsonb, 0, 'Le subjonctif II de *sollen* adoucit la consigne en conseil.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('allemand');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('allemand')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 249 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 249 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
